  ): React.CSSProperties => ({
    display: "inline-block",
    padding: "2px 8px",
    borderRadius: "10px",
    fontSize: "11px",
    fontWeight: 600,
    lineHeight: "18px",
    background:
      tone === "success"
        ? "#c8f9e8"
        : tone === "info"
          ? "#e4e5f7"
          : "#e4e5e7",
    color:
      tone === "success"
        ? "#0d6832"
        : tone === "info"
          ? "#3b3f8c"
          : "#6d7175",
  });

  return (
    <s-page heading="Dashboard">
      {/* Primary action */}
      <s-button slot="primary-action" variant="primary" href="/app/size-charts">
        Create Size Chart
      </s-button>

      {/* ================================================================ */}
      {/* SETUP GUIDE — collapsible, prominent                              */}
      {/* ================================================================ */}
      {!isSetupComplete && (
        <s-section>
          <div style={cardStyle}>
            {/* Header row */}
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <div>
                <p style={sectionTitle}>Setup guide</p>
                <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
                  Use this personalized guide to get you started with Size Chart &
                  Recommender.
                </p>
              </div>
              <div style={{ display: "flex", gap: "8px" }}>
                <button
                  onClick={() => setSetupOpen(!setupOpen)}
                  style={{
                    background: "none",
                    border: "1px solid #c9cccf",
                    borderRadius: "8px",
                    padding: "6px 12px",
                    cursor: "pointer",
