        </div>
      </s-section>

      {/* ================================================================ */}
      {/* CTA BANNER — show size charts for all products                    */}
      {/* ================================================================ */}
      {chartCount === 0 && (
        <s-section>
          <div
            style={{
              ...cardStyle,
              background: "#f7f7f7",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              gap: "24px",
            }}
          >
            <div>
              <p
                style={{
                  fontSize: "16px",
                  fontWeight: 650,
                  color: "#202223",
                  margin: "0 0 6px",
                }}
              >
                Show size charts for all your products
              </p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "0 0 16px",
                }}
              >
                Help your customers easily find the right size for every
                product. Reduce returns by up to 40%.
              </p>
              <div style={{ display: "flex", gap: "8px" }}>
                <s-button variant="primary" href="/app/size-charts">
                  Create chart
                </s-button>
                <s-button href="/app/pricing">View plans</s-button>
              </div>
            </div>
            {/* Simple visual indicator */}
            <div
              style={{
                width: "80px",
                height: "80px",
                borderRadius: "50%",
                background: "#e8f0fe",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: "32px",
                flexShrink: 0,
              }}
            >
              📏
            </div>
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* RECENT SIZE CHARTS                                                */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
          <div
            style={{
