          </div>

          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              background: "#fafafa",
              border: "1px solid #e3e3e3",
              borderRadius: "8px",
              padding: "12px 16px",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <span style={{ fontWeight: 600, fontSize: "14px", color: "#202223" }}>
                App Block
              </span>
              <span style={badgeStyle("neutral")}>Optional</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
              <span style={badgeStyle(activeChartCount > 0 ? "success" : "neutral")}>
                {activeChartCount > 0 ? "Active" : "Inactive"}
              </span>
            </div>
          </div>
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Plan & Usage                                              */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Your plan">
        <s-stack direction="block" gap="base">
          <s-stack direction="inline" gap="small-200">
            <s-badge tone={isFreePlan ? "neutral" : "success"}>
              {plan.name}
            </s-badge>
            <s-text tone="neutral">
              {plan.price === 0 ? "Free" : `$${plan.price}/mo`}
            </s-text>
          </s-stack>

          {isFreePlan && maxCharts > 0 && (
            <s-stack direction="block" gap="small-200">
              <s-text tone="neutral">
                {chartCount} / {maxCharts} charts used
              </s-text>
              <div style={progressBarBg}>
                <div
                  style={{
                    ...progressBarFill,
                    width: `${Math.min(100, Math.round((chartCount / maxCharts) * 100))}%`,
                    background:
                      chartCount >= maxCharts ? "#d72c0d" : "#1a73e8",
                  }}
                />
              </div>
            </s-stack>
          )}

          <s-unordered-list>
            {plan.features.slice(0, 4).map((f, i) => (
              <s-list-item key={i}>{f}</s-list-item>
            ))}
          </s-unordered-list>

          {isFreePlan && (
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick links                                               */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick links">
        <s-unordered-list>
          <s-list-item>
            <s-link href="/app/size-charts">Size Charts</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/widget">Widget Appearance</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/recommender">AI Recommender</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/analytics">Analytics</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/settings">Settings</s-link>
          </s-list-item>
        </s-unordered-list>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Help & Resources                                          */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Need help?">
        <s-stack direction="block" gap="base">
          <s-text tone="neutral">
            We respond within 2 hours.
          </s-text>
          <s-unordered-list>
            <s-list-item>
              <s-link href="mailto:support@sizechart.app">
                Email support
              </s-link>
            </s-list-item>
            <s-list-item>
              <s-link href="/app/settings">App settings</s-link>
            </s-list-item>
          </s-unordered-list>
          {plan.limits.prioritySupport && (
            <s-badge tone="success">Priority support</s-badge>
          )}
        </s-stack>
      </s-section>
    </s-page>
  );
}

