   1→import { useEffect, useRef, useState } from "react";
   2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
   3→import { useLoaderData, useFetcher, redirect } from "react-router";
   4→import { useAppBridge } from "@shopify/app-bridge-react";
   5→import { authenticate } from "../shopify.server";
   6→import db from "../db.server";
   7→
   8→// ---------------------------------------------------------------------------
   9→// Types
  10→// ---------------------------------------------------------------------------
  11→
  12→interface ChartData {
  13→  headers: string[];
  14→  units: { default: string; available: string[] };
  15→  rows: Record<string, string>[];
  16→}
  17→
  18→interface Assignment {
  19→  id: string;
  20→  assignmentType: string;
  21→  assignmentValue: string;
  22→}
  23→
  24→// ---------------------------------------------------------------------------
  25→// Loader
  26→// ---------------------------------------------------------------------------
  27→
  28→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  29→  const { session } = await authenticate.admin(request);
  30→  const shop = session.shop;
  31→  const id = params.id;
  32→
  33→  if (!id) throw new Response("Not found", { status: 404 });
  34→
  35→  if (id === "new") {
  36→    return {
  37→      chart: null as null,
  38→      assignments: [] as Assignment[],
  39→      isNew: true,
  40→    };
  41→  }
  42→
  43→  const chart = await db.sizeChart.findFirst({
  44→    where: { id, shop },
  45→    include: { assignments: true },
  46→  });
  47→
  48→  if (!chart) {
  49→    throw new Response("Not found", { status: 404 });
  50→  }
  51→
  52→  return {
  53→    chart: {
  54→      id: chart.id,
  55→      name: chart.name,
  56→      category: chart.category,
  57→      status: chart.status,
  58→      data: chart.data,
  59→      createdAt: chart.createdAt.toISOString(),
  60→      updatedAt: chart.updatedAt.toISOString(),
  61→    },
  62→    assignments: chart.assignments.map((a) => ({
  63→      id: a.id,
  64→      assignmentType: a.assignmentType,
  65→      assignmentValue: a.assignmentValue,
  66→    })),
  67→    isNew: false,
  68→  };
  69→};
  70→
  71→// ---------------------------------------------------------------------------
  72→// Action
  73→// ---------------------------------------------------------------------------
  74→
  75→export const action = async ({ request, params }: ActionFunctionArgs) => {
  76→  const { session } = await authenticate.admin(request);
  77→  const shop = session.shop;
  78→  const id = params.id;
  79→  if (!id) return { error: "Missing chart ID" };
  80→  const formData = await request.formData();
  81→  const intent = formData.get("intent") as string;
  82→
  83→  try {
  84→    switch (intent) {
  85→      case "save": {
  86→        const name = formData.get("name") as string;
  87→        const category = formData.get("category") as string;
  88→        const status = formData.get("status") as string;
  89→        const dataRaw = formData.get("data") as string;
  90→
  91→        if (!name?.trim()) return { error: "Chart name is required" };
  92→
  93→        let parsedData: ChartData;
  94→        try {
  95→          parsedData = JSON.parse(dataRaw) as ChartData;
  96→        } catch {
  97→          return { error: "Invalid chart data. Please try again." };
  98→        }
  99→
 100→        if (id === "new") {
 101→          const chart = await db.sizeChart.create({
 102→            data: {
 103→              shop,
 104→              name: name.trim(),
 105→              category,
 106→              status,
 107→              data: JSON.stringify(parsedData),
 108→            },
 109→          });
 110→          return redirect(`/app/size-charts/${chart.id}?saved=1`);
 111→        }
 112→
 113→        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
 114→        if (!existing) return { error: "Chart not found" };
 115→
 116→        await db.sizeChart.update({
 117→          where: { id },
 118→          data: {
 119→            name: name.trim(),
 120→            category,
 121→            status,
 122→            data: JSON.stringify(parsedData),
 123→          },
 124→        });
 125→        return { ok: true, message: "Chart saved successfully" };
 126→      }
 127→
 128→      case "toggle-status": {
 129→        const chart = await db.sizeChart.findFirst({ where: { id, shop } });
 130→        if (!chart) return { error: "Chart not found" };
 131→        const newStatus = chart.status === "active" ? "draft" : "active";
 132→        await db.sizeChart.update({ where: { id }, data: { status: newStatus } });
 133→        return {
 134→          ok: true,
 135→          message: newStatus === "active" ? "Chart published" : "Chart unpublished",
 136→          newStatus,
 137→        };
 138→      }
 139→
 140→      case "add-assignment": {
 141→        const assignmentType = formData.get("assignmentType") as string;
 142→        const assignmentValue = formData.get("assignmentValue") as string;
 143→
 144→        if (!assignmentValue?.trim()) {
 145→          return { error: "Assignment value is required" };
 146→        }
 147→
 148→        await db.chartAssignment.upsert({
 149→          where: {
 150→            shop_sizeChartId_assignmentType_assignmentValue: {
 151→              shop,
 152→              sizeChartId: id,
 153→              assignmentType,
 154→              assignmentValue: assignmentValue.trim(),
 155→            },
 156→          },
 157→          create: {
 158→            shop,
 159→            sizeChartId: id,
 160→            assignmentType,
 161→            assignmentValue: assignmentValue.trim(),
 162→          },
 163→          update: {},
 164→        });
 165→        return { ok: true, message: "Assignment added" };
 166→      }
 167→
 168→      case "remove-assignment": {
 169→        const assignmentId = formData.get("assignmentId") as string;
 170→        await db.chartAssignment.deleteMany({
 171→          where: { id: assignmentId, shop },
 172→        });
 173→        return { ok: true, message: "Assignment removed" };
 174→      }
 175→
 176→      case "delete": {
 177→        await db.sizeChart.deleteMany({ where: { id, shop } });
 178→        return redirect("/app/size-charts");
 179→      }
 180→
 181→      default:
 182→        return { error: "Unknown action" };
 183→    }
 184→  } catch (error) {
 185→    const message =
 186→      error instanceof Error ? error.message : "An unexpected error occurred";
 187→    if (message.includes("Unique constraint")) {
 188→      return { error: "A chart with this name already exists." };
 189→    }
 190→    return { error: message };
 191→  }
 192→};
 193→
 194→// ---------------------------------------------------------------------------
 195→// Constants
 196→// ---------------------------------------------------------------------------
 197→
 198→const CATEGORIES = [
 199→  { value: "general", label: "General" },
 200→  { value: "tops", label: "Tops" },
 201→  { value: "bottoms", label: "Bottoms" },
 202→  { value: "dresses", label: "Dresses" },
 203→  { value: "shoes", label: "Shoes" },
 204→  { value: "kids", label: "Kids" },
 205→  { value: "rings", label: "Rings" },
 206→  { value: "sportswear", label: "Sportswear" },
 207→];
 208→
 209→const ASSIGNMENT_TYPES = [
 210→  { value: "product", label: "Product ID" },
 211→  { value: "collection", label: "Collection ID" },
 212→  { value: "tag", label: "Product Tag" },
 213→  { value: "product_type", label: "Product Type" },
 214→  { value: "all", label: "All Products" },
 215→];
 216→
 217→function formatDate(iso: string): string {
 218→  return new Date(iso).toLocaleDateString("en-US", {
 219→    month: "short",
 220→    day: "numeric",
 221→    year: "numeric",
 222→    hour: "2-digit",
 223→    minute: "2-digit",
 224→  });
 225→}
 226→
 227→function makeDefaultData(): ChartData {
 228→  return {
 229→    headers: ["Size", "Chest", "Waist", "Hips"],
 230→    units: { default: "in", available: ["in", "cm"] },
 231→    rows: [
 232→      { Size: "S", Chest: "", Waist: "", Hips: "" },
 233→      { Size: "M", Chest: "", Waist: "", Hips: "" },
 234→      { Size: "L", Chest: "", Waist: "", Hips: "" },
 235→    ],
 236→  };
 237→}
 238→
 239→function parseChartData(raw: string): ChartData {
 240→  try {
 241→    const parsed = JSON.parse(raw) as ChartData;
 242→    if (
 243→      Array.isArray(parsed.headers) &&
 244→      parsed.units &&
 245→      Array.isArray(parsed.rows)
 246→    ) {
 247→      return parsed;
 248→    }
 249→  } catch {
 250→    // fall through
 251→  }
 252→  return makeDefaultData();
 253→}
 254→
 255→// ---------------------------------------------------------------------------
 256→// Table Editor Component
 257→// ---------------------------------------------------------------------------
 258→
 259→interface TableEditorProps {
 260→  data: ChartData;
 261→  onChange: (data: ChartData) => void;
 262→}
 263→
 264→function TableEditor({ data, onChange }: TableEditorProps) {
 265→  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);
 266→
 267→  const updateCell = (rowIndex: number, header: string, value: string) => {
 268→    const newRows = data.rows.map((row, i) => {
 269→      if (i !== rowIndex) return row;
 270→      return { ...row, [header]: value };
 271→    });
 272→    onChange({ ...data, rows: newRows });
 273→  };
 274→
 275→  const updateHeader = (headerIndex: number, value: string) => {
 276→    const oldHeader = data.headers[headerIndex];
 277→    const newHeaders = data.headers.map((h, i) => (i === headerIndex ? value : h));
 278→    const newRows = data.rows.map((row) => {
 279→      const newRow: Record<string, string> = {};
 280→      data.headers.forEach((h, i) => {
 281→        const key = i === headerIndex ? value : h;
 282→        newRow[key] = row[h] ?? "";
 283→      });
 284→      return newRow;
 285→    });
 286→    onChange({ ...data, headers: newHeaders, rows: newRows });
 287→    // suppress unused variable warning
 288→    void oldHeader;
 289→  };
 290→
 291→  const addRow = () => {
 292→    const emptyRow: Record<string, string> = {};
 293→    data.headers.forEach((h) => {
 294→      emptyRow[h] = "";
 295→    });
 296→    onChange({ ...data, rows: [...data.rows, emptyRow] });
 297→  };
 298→
 299→  const removeRow = (rowIndex: number) => {
 300→    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
 301→  };
 302→
 303→  const addColumn = () => {
 304→    const newHeader = `Column ${data.headers.length + 1}`;
 305→    const newHeaders = [...data.headers, newHeader];
 306→    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
 307→    onChange({ ...data, headers: newHeaders, rows: newRows });
 308→  };
 309→
 310→  const removeColumn = (headerIndex: number) => {
 311→    if (data.headers.length <= 1) return;
 312→    const removedHeader = data.headers[headerIndex];
 313→    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
 314→    const newRows = data.rows.map((row) => {
 315→      const newRow: Record<string, string> = {};
 316→      newHeaders.forEach((h) => {
 317→        newRow[h] = row[h] ?? "";
 318→      });
 319→      return newRow;
 320→    });
 321→    onChange({ ...data, headers: newHeaders, rows: newRows });
 322→    void removedHeader;
 323→  };
 324→
 325→  const toggleUnit = (unit: string) => {
 326→    onChange({ ...data, units: { ...data.units, default: unit } });
 327→  };
 328→
 329→  return (
 330→    <div>
 331→      <div
 332→        style={{
 333→          display: "flex",
 334→          alignItems: "center",
 335→          gap: "8px",
 336→          marginBottom: "16px",
 337→        }}
 338→      >
 339→        <s-text tone="neutral">Unit system:</s-text>
 340→        {data.units.available.map((unit) => (
 341→          <button
 342→            key={unit}
 343→            type="button"
 344→            onClick={() => toggleUnit(unit)}
 345→            style={{
 346→              padding: "4px 12px",
 347→              borderRadius: "4px",
 348→              border: "1px solid",
 349→              borderColor: data.units.default === unit ? "#2c6ecb" : "#8c9196",
 350→              background: data.units.default === unit ? "#f0f7ff" : "#fff",
 351→              color: data.units.default === unit ? "#2c6ecb" : "#333",
 352→              fontWeight: data.units.default === unit ? 600 : 400,
 353→              cursor: "pointer",
 354→              fontSize: "13px",
 355→            }}
 356→          >
 357→            {unit}
 358→          </button>
 359→        ))}
 360→        <div style={{ marginLeft: "auto" }}>
 361→          <s-text tone="neutral">
 362→            {data.rows.length} rows · {data.headers.length} columns
 363→          </s-text>
 364→        </div>
 365→      </div>
 366→
 367→      <div style={{ overflowX: "auto" }}>
 368→        <table
 369→          style={{
 370→            width: "100%",
 371→            borderCollapse: "collapse",
 372→            fontSize: "14px",
 373→          }}
 374→        >
 375→          <thead>
 376→            <tr>
 377→              {data.headers.map((header, hi) => (
 378→                <th
 379→                  key={hi}
 380→                  style={{
 381→                    background: "#f6f6f7",
 382→                    border: "1px solid #e1e3e5",
 383→                    padding: "0",
 384→                    position: "relative",
 385→                    minWidth: "100px",
 386→                  }}
 387→                >
 388→                  <div
 389→                    style={{
 390→                      display: "flex",
 391→                      alignItems: "center",
 392→                      padding: "4px 4px 4px 8px",
 393→                    }}
 394→                  >
 395→                    <input
 396→                      ref={(el) => {
 397→                        headerInputRefs.current[hi] = el;
 398→                      }}
 399→                      value={header}
 400→                      onChange={(e) =>
 401→                        updateHeader(hi, (e.target as HTMLInputElement).value)
 402→                      }
 403→                      style={{
 404→                        flex: 1,
 405→                        border: "none",
 406→                        background: "transparent",
 407→                        fontWeight: 600,
 408→                        fontSize: "13px",
 409→                        color: "#202223",
 410→                        padding: "6px 4px",
 411→                        outline: "none",
 412→                        minWidth: "60px",
 413→                      }}
 414→                      placeholder={`Column ${hi + 1}`}
 415→                    />
 416→                    {data.headers.length > 1 && (
 417→                      <button
 418→                        type="button"
 419→                        onClick={() => removeColumn(hi)}
 420→                        title="Remove column"
 421→                        style={{
 422→                          background: "none",
 423→                          border: "none",
 424→                          cursor: "pointer",
 425→                          color: "#8c9196",
 426→                          padding: "2px 4px",
 427→                          borderRadius: "3px",
 428→                          fontSize: "14px",
 429→                          lineHeight: 1,
 430→                          flexShrink: 0,
 431→                        }}
 432→                        onMouseEnter={(e) => {
 433→                          (e.currentTarget as HTMLButtonElement).style.color = "#d82c0d";
 434→                        }}
 435→                        onMouseLeave={(e) => {
 436→                          (e.currentTarget as HTMLButtonElement).style.color = "#8c9196";
 437→                        }}
 438→                      >
 439→                        ×
 440→                      </button>
 441→                    )}
 442→                  </div>
 443→                </th>
 444→              ))}
 445→              <th
 446→                style={{
 447→                  background: "#f6f6f7",
 448→                  border: "1px solid #e1e3e5",
 449→                  padding: "8px",
 450→                  width: "48px",
 451→                }}
 452→              >
 453→                <button
 454→                  type="button"
 455→                  onClick={addColumn}
 456→                  title="Add column"
 457→                  style={{
 458→                    background: "none",
 459→                    border: "none",
 460→                    cursor: "pointer",
 461→                    color: "#2c6ecb",
 462→                    fontSize: "18px",
 463→                    lineHeight: 1,
 464→                    padding: "0 4px",
 465→                  }}
 466→                >
 467→                  +
 468→                </button>
 469→              </th>
 470→            </tr>
 471→          </thead>
 472→          <tbody>
 473→            {data.rows.map((row, ri) => (
 474→              <tr
 475→                key={ri}
 476→                style={{ background: ri % 2 === 0 ? "#fff" : "#fafbfb" }}
 477→              >
 478→                {data.headers.map((header, hi) => (
 479→                  <td
 480→                    key={hi}
 481→                    style={{
 482→                      border: "1px solid #e1e3e5",
 483→                      padding: "0",
 484→                    }}
 485→                  >
 486→                    <input
 487→                      value={row[header] ?? ""}
 488→                      onChange={(e) =>
 489→                        updateCell(ri, header, (e.target as HTMLInputElement).value)
 490→                      }
 491→                      style={{
 492→                        width: "100%",
