 496→                        fontSize: "13px",
 497→                        color: "#202223",
 498→                        outline: "none",
 499→                        boxSizing: "border-box",
 500→                      }}
 501→                      placeholder="—"
 502→                    />
 503→                  </td>
 504→                ))}
 505→                <td
 506→                  style={{
 507→                    border: "1px solid #e1e3e5",
 508→                    padding: "4px",
 509→                    textAlign: "center",
 510→                    background: ri % 2 === 0 ? "#fff" : "#fafbfb",
 511→                  }}
 512→                >
 513→                  <button
 514→                    type="button"
 515→                    onClick={() => removeRow(ri)}
 516→                    title="Remove row"
 517→                    style={{
 518→                      background: "none",
 519→                      border: "none",
 520→                      cursor: "pointer",
 521→                      color: "#8c9196",
 522→                      fontSize: "16px",
 523→                      lineHeight: 1,
 524→                      padding: "2px 6px",
 525→                      borderRadius: "3px",
 526→                    }}
 527→                    onMouseEnter={(e) => {
