 546→                }}
 547→              >
 548→                <button
 549→                  type="button"
 550→                  onClick={addRow}
 551→                  style={{
 552→                    background: "none",
 553→                    border: "none",
 554→                    cursor: "pointer",
 555→                    color: "#2c6ecb",
 556→                    fontSize: "13px",
 557→                    fontWeight: 500,
 558→                    padding: "0",
 559→                  }}
 560→                >
 561→                  + Add row
 562→                </button>
 563→              </td>
 564→            </tr>
 565→          </tbody>
 566→        </table>
 567→      </div>
 568→    </div>
 569→  );
 570→}
 571→
 572→// ---------------------------------------------------------------------------
 573→// Preview Component
