 575→
 576→interface ChartPreviewProps {
 577→  data: ChartData;
 578→  name: string;
 579→}
 580→
 581→function ChartPreview({ data, name }: ChartPreviewProps) {
 582→  return (
 583→    <div
 584→      style={{
 585→        border: "1px solid #e1e3e5",
