 609→        >
 610→          <thead>
 611→            <tr>
 612→              {data.headers.map((h, i) => (
 613→                <th
 614→                  key={i}
 615→                  style={{
 616→                    background: "#f6f6f7",
 617→                    padding: "8px 12px",
 618→                    textAlign: "left",
