 761→  };
 762→
 763→  const handleAddAssignment = () => {
 764→    if (!newAssignmentValue.trim() && newAssignmentType !== "all") return;
 765→    const formData = new FormData();
 766→    formData.set("intent", "add-assignment");
 767→    formData.set("assignmentType", newAssignmentType);
 768→    formData.set(
 769→      "assignmentValue",
 770→      newAssignmentType === "all" ? "*" : newAssignmentValue.trim()
 771→    );
 772→    assignmentFetcher.submit(formData, { method: "post" });
 773→    setAssignments((prev) => [
 774→      ...prev,
 775→      {
 776→        id: `temp-${Date.now()}`,
 777→        assignmentType: newAssignmentType,
 778→        assignmentValue: newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
