 846→              }}
 847→            />
 848→          </s-stack>
 849→
 850→          <s-stack direction="inline" gap="base">
 851→            <div style={{ flex: 1 }}>
 852→              <s-stack direction="block" gap="small-100">
 853→                <s-text>Category</s-text>
