1053→            </s-stack>
1054→            <s-stack direction="block" gap="small-100">
1055→              <s-text tone="neutral">Last updated</s-text>
1056→              <s-text>{formatDate(chart.updatedAt)}</s-text>
1057→            </s-stack>
1058→            <s-stack direction="block" gap="small-100">
