import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan } from "../lib/plans";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  const d = typeof date === "string" ? new Date(date) : date;
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

  const [
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    subscription,
    recentCharts,
    widgetConfig,
    recommenderConfig,
    assignmentCount,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.sizeChart.count({ where: { shop, status: "active" } }),
    db.sizeChart.count({ where: { shop, status: "draft" } }),
    db.analyticsEvent.count({
      where: { shop, eventType: "view", createdAt: { gte: thirtyDaysAgo } },
    }),
    db.analyticsEvent.count({ where: { shop, eventType: "recommend" } }),
    db.subscription.findUnique({ where: { shop } }),
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      take: 5,
      select: {
        id: true,
        name: true,
        category: true,
        status: true,
        updatedAt: true,
        _count: { select: { assignments: true } },
      },
    }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.chartAssignment.count({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  const hasChart = chartCount > 0;
  const hasAssignment = assignmentCount > 0;
  const hasWidget = widgetConfig !== null;
  const hasRecommender =
    recommenderConfig !== null && recommenderConfig.enabled;

  const setupSteps = [
    {
      key: "create-chart",
      title: "Create your first size chart",
      description:
        "Choose from 9 ready-made templates or build a custom chart from scratch.",
      done: hasChart,
      actionLabel: "Create chart",
      actionUrl: "/app/size-charts",
    },
    {
      key: "customize-widget",
      title: "Style your size chart widget",
      description:
        "Customize colors, layout, and text to match your store's brand.",
      done: hasWidget,
      actionLabel: "Go to Appearance",
      actionUrl: "/app/widget",
    },
    {
      key: "assign-products",
      title: "Assign chart to products",
      description:
        "Link your chart to products, collections, or tags so it shows automatically.",
      done: hasAssignment,
      actionLabel: "Assign products",
      actionUrl: "/app/size-charts",
    },
  ];

  const completedCount = setupSteps.filter((s) => s.done).length;

  return {
    shop,
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts: recentCharts.map((c) => ({
      ...c,
      assignmentCount: c._count.assignments,
      updatedAt: c.updatedAt.toISOString(),
    })),
    hasRecommender,
    setupSteps,
    completedCount,
    totalSteps: setupSteps.length,
  };
};

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function Dashboard() {
  const {
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts,
    setupSteps,
    completedCount,
    totalSteps,
  } = useLoaderData<typeof loader>();

  const [setupOpen, setSetupOpen] = useState(true);
  const [expandedStep, setExpandedStep] = useState<string | null>(
    setupSteps.find((s) => !s.done)?.key ?? null,
  );

  const isSetupComplete = completedCount === totalSteps;
  const isFreePlan = plan.id === "free";
  const maxCharts = plan.limits.maxCharts;

  // --- Styles ---
  const cardStyle: React.CSSProperties = {
    background: "#ffffff",
    border: "1px solid #e3e3e3",
    borderRadius: "12px",
    padding: "20px",
  };

  const statCardStyle: React.CSSProperties = {
    ...cardStyle,
    flex: "1 1 0",
    minWidth: "140px",
    textAlign: "center" as const,
  };

  const statNumber: React.CSSProperties = {
    fontSize: "28px",
    fontWeight: 650,
    color: "#202223",
    lineHeight: 1.2,
  };

  const statLabel: React.CSSProperties = {
    fontSize: "13px",
    color: "#6d7175",
    marginTop: "4px",
  };

  const statSub: React.CSSProperties = {
    fontSize: "12px",
    color: "#8c9196",
    marginTop: "2px",
  };

  const sectionTitle: React.CSSProperties = {
    fontSize: "15px",
    fontWeight: 650,
    color: "#202223",
    margin: 0,
  };

  const stepRow: React.CSSProperties = {
    display: "flex",
    alignItems: "flex-start",
    gap: "12px",
    padding: "14px 0",
    borderBottom: "1px solid #f1f1f1",
    cursor: "pointer",
  };

  const stepCircle = (done: boolean): React.CSSProperties => ({
    width: "22px",
    height: "22px",
    borderRadius: "50%",
    border: done ? "none" : "2px solid #c9cccf",
    background: done ? "#1a73e8" : "transparent",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    flexShrink: 0,
    marginTop: "1px",
    color: "#fff",
    fontSize: "12px",
    fontWeight: 700,
  });

  const progressBarBg: React.CSSProperties = {
    height: "6px",
    background: "#e4e5e7",
    borderRadius: "3px",
    overflow: "hidden",
    marginTop: "8px",
    marginBottom: "4px",
  };

  const progressBarFill: React.CSSProperties = {
    height: "100%",
    background: "#1a73e8",
    borderRadius: "3px",
    width: `${Math.round((completedCount / totalSteps) * 100)}%`,
    transition: "width 0.3s ease",
  };

  const chartRow: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "12px 0",
    borderBottom: "1px solid #f1f1f1",
  };

  const badgeStyle = (
    tone: "success" | "neutral" | "info",
  ): React.CSSProperties => ({
    display: "inline-block",
    padding: "2px 8px",
    borderRadius: "10px",
    fontSize: "11px",
    fontWeight: 600,
    lineHeight: "18px",
    background:
      tone === "success"
        ? "#c8f9e8"
        : tone === "info"
          ? "#e4e5f7"
          : "#e4e5e7",
    color:
      tone === "success"
        ? "#0d6832"
        : tone === "info"
          ? "#3b3f8c"
          : "#6d7175",
  });

  return (
    <s-page heading="Dashboard">
      {/* Primary action */}
      <s-button slot="primary-action" variant="primary" href="/app/size-charts">
        Create Size Chart
      </s-button>

      {/* ================================================================ */}
      {/* SETUP GUIDE — collapsible, prominent                              */}
      {/* ================================================================ */}
      {!isSetupComplete && (
        <s-section>
          <div style={cardStyle}>
            {/* Header row */}
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <div>
                <p style={sectionTitle}>Setup guide</p>
                <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
                  Use this personalized guide to get you started with Size Chart &
                  Recommender.
                </p>
              </div>
              <div style={{ display: "flex", gap: "8px" }}>
                <button
                  onClick={() => setSetupOpen(!setupOpen)}
                  style={{
                    background: "none",
                    border: "1px solid #c9cccf",
                    borderRadius: "8px",
                    padding: "6px 12px",
                    cursor: "pointer",
                    fontSize: "13px",
                    color: "#202223",
                  }}
                >
                  {setupOpen ? "Hide" : "Show"}
                </button>
              </div>
            </div>

            {/* Progress */}
            <p
              style={{
                fontSize: "13px",
                color: "#6d7175",
                margin: "12px 0 0",
              }}
            >
              {completedCount} of {totalSteps} steps completed
            </p>
            <div style={progressBarBg}>
              <div style={progressBarFill} />
            </div>

            {/* Steps */}
            {setupOpen && (
              <div style={{ marginTop: "8px" }}>
                {setupSteps.map((step) => (
                  <div key={step.key}>
                    <div
                      style={stepRow}
                      onClick={() =>
                        setExpandedStep(
                          expandedStep === step.key ? null : step.key,
                        )
                      }
                    >
                      <div style={stepCircle(step.done)}>
                        {step.done && "✓"}
                      </div>
                      <div style={{ flex: 1 }}>
                        <p
                          style={{
                            margin: 0,
                            fontSize: "14px",
                            fontWeight: 600,
                            color: step.done ? "#8c9196" : "#202223",
                            textDecoration: step.done
                              ? "line-through"
                              : "none",
                          }}
                        >
                          {step.title}
                        </p>

                        {expandedStep === step.key && !step.done && (
                          <div style={{ marginTop: "8px" }}>
                            <p
                              style={{
                                fontSize: "13px",
                                color: "#6d7175",
                                margin: "0 0 12px",
                              }}
                            >
                              {step.description}
                            </p>
                            <s-button
                              variant="primary"
                              href={step.actionUrl}
                            >
                              {step.actionLabel}
                            </s-button>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* STATS OVERVIEW                                                    */}
      {/* ================================================================ */}
      <s-section>
        <div
          style={{
            display: "flex",
            gap: "16px",
            flexWrap: "wrap",
          }}
        >
          <div style={statCardStyle}>
            <div style={statNumber}>{chartCount}</div>
            <div style={statLabel}>Total charts</div>
            <div style={statSub}>
              {activeChartCount} active · {draftChartCount} draft
            </div>
          </div>

          <div style={statCardStyle}>
            <div style={statNumber}>{activeChartCount}</div>
            <div style={statLabel}>Published charts</div>
            <div style={statSub}>Visible on storefront</div>
          </div>

          <div style={statCardStyle}>
            <div style={statNumber}>{monthlyViews}x</div>
            <div style={statLabel}>Views — current month</div>
            <div style={statSub}>Last 30 days</div>
          </div>

          <div style={statCardStyle}>
            <div style={statNumber}>{totalRecommendations}</div>
            <div style={statLabel}>AI recommendations</div>
            <div style={statSub}>
              {plan.limits.aiRecommender ? "Active" : "Upgrade to unlock"}
            </div>
          </div>
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* CTA BANNER — show size charts for all products                    */}
      {/* ================================================================ */}
      {chartCount === 0 && (
        <s-section>
          <div
            style={{
              ...cardStyle,
              background: "#f7f7f7",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              gap: "24px",
            }}
          >
            <div>
              <p
                style={{
                  fontSize: "16px",
                  fontWeight: 650,
                  color: "#202223",
                  margin: "0 0 6px",
                }}
              >
                Show size charts for all your products
              </p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "0 0 16px",
                }}
              >
                Help your customers easily find the right size for every
                product. Reduce returns by up to 40%.
              </p>
              <div style={{ display: "flex", gap: "8px" }}>
                <s-button variant="primary" href="/app/size-charts">
                  Create chart
                </s-button>
                <s-button href="/app/pricing">View plans</s-button>
              </div>
            </div>
            {/* Simple visual indicator */}
            <div
              style={{
                width: "80px",
                height: "80px",
                borderRadius: "50%",
                background: "#e8f0fe",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: "32px",
                flexShrink: 0,
              }}
            >
              📏
            </div>
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* RECENT SIZE CHARTS                                                */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "12px",
            }}
          >
            <p style={sectionTitle}>
              {chartCount > 0 ? "Recent size charts" : "Create your size chart!"}
            </p>
            {chartCount > 0 && (
              <s-link href="/app/size-charts">View all</s-link>
            )}
          </div>

          {recentCharts.length === 0 ? (
            <div style={{ textAlign: "center", padding: "32px 0" }}>
              <div
                style={{
                  width: "72px",
                  height: "72px",
                  borderRadius: "50%",
                  background: "#f0f5ff",
                  margin: "0 auto 16px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "28px",
                }}
              >
                📐
              </div>
              <p
                style={{
                  fontSize: "14px",
                  color: "#6d7175",
                  margin: "0 0 16px",
                }}
              >
                Create various types of size charts, AI Size Recommendations.
              </p>
              <s-button variant="primary" href="/app/size-charts">
                Create a Size Chart
              </s-button>
            </div>
          ) : (
            <div>
              {recentCharts.map((chart, i) => (
                <div
                  key={chart.id}
                  style={{
                    ...chartRow,
                    borderBottom:
                      i === recentCharts.length - 1
                        ? "none"
                        : "1px solid #f1f1f1",
                  }}
                >
                  <div>
                    <s-link href={`/app/size-charts/${chart.id}`}>
                      {chart.name}
                    </s-link>
                    <div
                      style={{
                        display: "flex",
                        gap: "8px",
                        marginTop: "4px",
                        alignItems: "center",
                      }}
                    >
                      <span style={badgeStyle("info")}>{chart.category}</span>
                      <span
                        style={badgeStyle(
                          chart.status === "active" ? "success" : "neutral",
                        )}
                      >
                        {chart.status === "active" ? "Active" : "Draft"}
                      </span>
                      <span style={{ fontSize: "12px", color: "#8c9196" }}>
                        {chart.assignmentCount > 0
                          ? `${chart.assignmentCount} product${chart.assignmentCount > 1 ? "s" : ""}`
                          : "No assignments"}
                      </span>
                    </div>
                  </div>
                  <span style={{ fontSize: "12px", color: "#8c9196" }}>
                    {formatDate(chart.updatedAt)}
                  </span>
                </div>
              ))}
            </div>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ENABLE APP — app status                                           */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
          <p style={sectionTitle}>Enable app</p>
          <p
            style={{
              fontSize: "13px",
              color: "#6d7175",
              margin: "4px 0 16px",
            }}
          >
            Keep the app active to display size charts on your store.
          </p>

          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              background: "#fafafa",
              border: "1px solid #e3e3e3",
              borderRadius: "8px",
              padding: "12px 16px",
              marginBottom: "8px",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <span style={{ fontWeight: 600, fontSize: "14px", color: "#202223" }}>
                Theme App Extension
              </span>
              <span style={badgeStyle("info")}>Required</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
              <span style={badgeStyle(activeChartCount > 0 ? "success" : "neutral")}>
                {activeChartCount > 0 ? "Active" : "Inactive"}
              </span>
            </div>
          </div>

          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              background: "#fafafa",
              border: "1px solid #e3e3e3",
              borderRadius: "8px",
              padding: "12px 16px",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <span style={{ fontWeight: 600, fontSize: "14px", color: "#202223" }}>
                App Block
              </span>
              <span style={badgeStyle("neutral")}>Optional</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
              <span style={badgeStyle(activeChartCount > 0 ? "success" : "neutral")}>
                {activeChartCount > 0 ? "Active" : "Inactive"}
              </span>
            </div>
          </div>
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Plan & Usage                                              */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Your plan">
        <s-stack direction="block" gap="base">
          <s-stack direction="inline" gap="small-200">
            <s-badge tone={isFreePlan ? "neutral" : "success"}>
              {plan.name}
            </s-badge>
            <s-text tone="neutral">
              {plan.price === 0 ? "Free" : `$${plan.price}/mo`}
            </s-text>
          </s-stack>

          {isFreePlan && maxCharts > 0 && (
            <s-stack direction="block" gap="small-200">
              <s-text tone="neutral">
                {chartCount} / {maxCharts} charts used
              </s-text>
              <div style={progressBarBg}>
                <div
                  style={{
                    ...progressBarFill,
                    width: `${Math.min(100, Math.round((chartCount / maxCharts) * 100))}%`,
                    background:
                      chartCount >= maxCharts ? "#d72c0d" : "#1a73e8",
                  }}
                />
              </div>
            </s-stack>
          )}

          <s-unordered-list>
            {plan.features.slice(0, 4).map((f, i) => (
              <s-list-item key={i}>{f}</s-list-item>
            ))}
          </s-unordered-list>

          {isFreePlan && (
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick links                                               */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick links">
        <s-unordered-list>
          <s-list-item>
            <s-link href="/app/size-charts">Size Charts</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/widget">Widget Appearance</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/recommender">AI Recommender</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/analytics">Analytics</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/settings">Settings</s-link>
          </s-list-item>
        </s-unordered-list>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Help & Resources                                          */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Need help?">
        <s-stack direction="block" gap="base">
          <s-text tone="neutral">
            We respond within 2 hours.
          </s-text>
          <s-unordered-list>
            <s-list-item>
              <s-link href="mailto:support@sizechart.app">
                Email support
              </s-link>
            </s-list-item>
            <s-list-item>
              <s-link href="/app/settings">App settings</s-link>
            </s-list-item>
          </s-unordered-list>
          {plan.limits.prioritySupport && (
            <s-badge tone="success">Priority support</s-badge>
          )}
        </s-stack>
      </s-section>
    </s-page>
  );
}

// --- Styles ---
const cardStyle: React.CSSProperties = {
  background: "#ffffff",
  border: "1px solid #e3e3e3",
  borderRadius: "12px",
  padding: "20px",
};

const statCardStyle: React.CSSProperties = {
  ...cardStyle,
  flex: "1 1 0",
  minWidth: "140px",
  textAlign: "center" as const,
};

const statNumber: React.CSSProperties = {
