 635→              >
 636→                {data.headers.map((h, hi) => (
 637→                  <td
 638→                    key={hi}
 639→                    style={{
 640→                      padding: "8px 12px",
 641→                      borderBottom: "1px solid #e1e3e5",
 642→                      borderRight:
