 644→                      color: row[h] ? "#202223" : "#8c9196",
 645→                    }}
 646→                  >
 647→                    {row[h] || "—"}
 648→                  </td>
 649→                ))}
 650→              </tr>
 651→            ))}
 652→          </tbody>
 653→        </table>
 654→      </div>
 655→      <div
 656→        style={{
 657→          padding: "8px 16px",
 658→          background: "#f6f6f7",
