 805→      >
 806→        Save
 807→      </s-button>
 808→
 809→      <s-button
 810→        slot="secondary-action"
 811→        onClick={handleToggleStatus}
 812→        loading={isTogglingStatus}
 813→        disabled={isNew || isTogglingStatus}
 814→      >
 815→        {status === "active" ? "Unpublish" : "Publish"}
 816→      </s-button>
 817→
 818→      {/* Chart Details */}
 819→      <s-section heading="Chart Details">
 820→        <s-stack direction="block" gap="base">
 821→          <s-stack direction="block" gap="small-100">
 822→            <s-text>Name</s-text>
 823→            <input
 824→              value={name}
 825→              onChange={(e) => setName((e.target as HTMLInputElement).value)}
 826→              placeholder="e.g. Women's Tops Size Chart"
 827→              style={{
 828→                width: "100%",
 829→                border: "1px solid #8c9196",
 830→                borderRadius: "6px",
 831→                padding: "8px 12px",
 832→                fontSize: "14px",
 833→                color: "#202223",
 834→                background: "#fff",
 835→                boxSizing: "border-box",
 836→                outline: "none",
 837→              }}
 838→              onFocus={(e) => {
 839→                (e.target as HTMLInputElement).style.borderColor = "#2c6ecb";
 840→                (e.target as HTMLInputElement).style.boxShadow =
 841→                  "0 0 0 3px rgba(44,110,203,0.15)";
 842→              }}
 843→              onBlur={(e) => {
 844→                (e.target as HTMLInputElement).style.borderColor = "#8c9196";
 845→                (e.target as HTMLInputElement).style.boxShadow = "none";
 846→              }}
 847→            />
 848→          </s-stack>
 849→
 850→          <s-stack direction="inline" gap="base">
 851→            <div style={{ flex: 1 }}>
 852→              <s-stack direction="block" gap="small-100">
 853→                <s-text>Category</s-text>
 854→                <select
 855→                  value={category}
 856→                  onChange={(e) => setCategory((e.target as HTMLSelectElement).value)}
 857→                  style={{
 858→                    width: "100%",
 859→                    border: "1px solid #8c9196",
 860→                    borderRadius: "6px",
 861→                    padding: "8px 12px",
 862→                    fontSize: "14px",
 863→                    color: "#202223",
 864→                    background: "#fff",
 865→                    boxSizing: "border-box",
 866→                    cursor: "pointer",
 867→                    outline: "none",
