import { useEffect, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, canCreateChart } from "../lib/plans";
import { SIZE_CHART_TEMPLATES, getCategories } from "../lib/templates";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [charts, subscription] = await Promise.all([
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      include: { assignments: true },
    }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");
  const templates = SIZE_CHART_TEMPLATES.map((t) => ({
    name: t.name,
    category: t.category,
    gender: t.gender,
    rowCount: t.data.rows.length,
  }));
  const categories = getCategories();

  return {
    charts,
    plan,
    templates,
    categories,
    canCreate: canCreateChart(plan.id, charts.length),
  };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "create-from-template": {
        const templateName = formData.get("templateName") as string;
        const template = SIZE_CHART_TEMPLATES.find((t) => t.name === templateName);
        if (!template) return { error: "Template not found" };

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return {
            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
          };
        }

        let name = template.name;
        const existing = await db.sizeChart.findUnique({
          where: { shop_name: { shop, name } },
        });
        if (existing) name = `${template.name} (${Date.now().toString(36)})`;

        const created = await db.sizeChart.create({
          data: {
            shop,
            name,
            category: template.category,
            data: JSON.stringify(template.data),
            status: "active",
          },
        });
        return { ok: true, message: `"${name}" created successfully`, redirectId: created.id };
      }

      case "create-blank": {
        const name = (formData.get("name") as string) || "Untitled Size Chart";
        const category = (formData.get("category") as string) || "general";

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return {
            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
          };
        }

        let uniqueName = name;
        const existing = await db.sizeChart.findUnique({
          where: { shop_name: { shop, name } },
        });
        if (existing) uniqueName = `${name} (${Date.now().toString(36)})`;

        const defaultData = {
          headers: ["Size", "Chest", "Waist", "Hips"],
          units: { default: "in", available: ["in", "cm"] },
          rows: [
            { Size: "S", Chest: "", Waist: "", Hips: "" },
            { Size: "M", Chest: "", Waist: "", Hips: "" },
            { Size: "L", Chest: "", Waist: "", Hips: "" },
          ],
        };

        const created = await db.sizeChart.create({
          data: {
            shop,
            name: uniqueName,
            category,
            data: JSON.stringify(defaultData),
            status: "draft",
          },
        });
        return { ok: true, message: `"${uniqueName}" created`, redirectId: created.id };
      }

      case "delete": {
        const id = formData.get("id") as string;
        await db.sizeChart.deleteMany({ where: { id, shop } });
        return { ok: true, message: "Chart deleted" };
      }

      case "duplicate": {
        const sourceId = formData.get("id") as string;
        const source = await db.sizeChart.findFirst({ where: { id: sourceId, shop } });
        if (!source) return { error: "Chart not found" };

        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        const chartCount = await db.sizeChart.count({ where: { shop } });
        if (!canCreateChart(plan.id, chartCount)) {
          return { error: "Chart limit reached. Upgrade your plan." };
        }

        const newName = `${source.name} (Copy)`;
        await db.sizeChart.create({
          data: {
            shop,
            name: newName,
            type: source.type,
            category: source.category,
            data: source.data,
            status: "draft",
          },
        });
        return { ok: true, message: `Duplicated as "${newName}"` };
      }

      case "toggle-status": {
        const chartId = formData.get("id") as string;
        const chart = await db.sizeChart.findFirst({ where: { id: chartId, shop } });
        if (!chart) return { error: "Chart not found" };

        const newStatus = chart.status === "active" ? "draft" : "active";
        await db.sizeChart.update({ where: { id: chartId }, data: { status: newStatus } });
        return {
          ok: true,
          message: `Chart ${newStatus === "active" ? "published" : "unpublished"}`,
        };
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    if (message.includes("Unique constraint")) {
      return { error: "A chart with this name already exists." };
    }
    return { error: message };
  }
};

type ActionData =
  | { ok: true; message: string; redirectId?: string }
  | { error: string };

const CATEGORY_LABELS: Record<string, string> = {
  tops: "Tops",
  bottoms: "Bottoms",
  dresses: "Dresses",
  shoes: "Shoes",
  kids: "Kids",
  rings: "Rings",
  sportswear: "Sportswear",
  general: "General",
};

function formatDate(date: string | Date): string {
  return new Date(date).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// Style constants — mirrors dashboard design language
// ---------------------------------------------------------------------------

const cardStyle: React.CSSProperties = {
  background: "#ffffff",
  border: "1px solid #e3e3e3",
  borderRadius: "12px",
  padding: "20px",
};

const sectionTitle: React.CSSProperties = {
  fontSize: "15px",
  fontWeight: 650,
  color: "#202223",
  margin: 0,
};

const badgeStyle = (tone: "success" | "neutral" | "info"): React.CSSProperties => ({
  display: "inline-block",
  padding: "2px 8px",
  borderRadius: "10px",
  fontSize: "11px",
  fontWeight: 600,
  lineHeight: "18px",
  background: tone === "success" ? "#c8f9e8" : tone === "info" ? "#e4e5f7" : "#e4e5e7",
  color: tone === "success" ? "#0d6832" : tone === "info" ? "#3b3f8c" : "#6d7175",
});

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function SizeCharts() {
  const { charts, plan, templates, categories, canCreate } =
    useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [showTemplates, setShowTemplates] = useState(false);
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [statusFilter, setStatusFilter] = useState("all");
  const [hoveredTemplate, setHoveredTemplate] = useState<string | null>(null);

  const isLoading = fetcher.state !== "idle";

  useEffect(() => {
    if (!fetcher.data) return;
    const data = fetcher.data as ActionData;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message);
      if ("redirectId" in data && data.redirectId) {
        window.location.href = `/app/size-charts/${data.redirectId}`;
      } else {
        setShowTemplates(false);
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error, { isError: true });
    }
  }, [fetcher.data, shopify]);

  const filteredCharts = charts.filter((chart) => {
    const matchesCategory =
      categoryFilter === "all" || chart.category === categoryFilter;
    const matchesStatus =
      statusFilter === "all" || chart.status === statusFilter;
    return matchesCategory && matchesStatus;
  });

  const publishedCount = charts.filter((c) => c.status === "active").length;
  const maxCharts = plan.limits.maxCharts;
  const isFreePlan = plan.id === "free";

  const progressPct =
    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
  const progressColor = publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";

  return (
    <s-page heading="Size Charts">
      {/* Primary action */}
      <s-button
        slot="primary-action"
        variant="primary"
        onClick={() => setShowTemplates(!showTemplates)}
        disabled={!canCreate || isLoading}
      >
        {canCreate
          ? showTemplates
            ? "Cancel"
            : "Create chart"
          : `Limit reached (${plan.limits.maxCharts})`}
      </s-button>

      {/* Subtitle */}
      <s-text tone="neutral">
        Manage your size charts and assign them to products
      </s-text>

      {/* ================================================================ */}
      {/* PLAN LIMIT BANNER                                                 */}
      {/* ================================================================ */}
      {!canCreate && (
        <s-section>
          <div
            style={{
              ...cardStyle,
              background: "#fff8ec",
              border: "1px solid #ffd79d",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: "16px",
            }}
          >
            <div>
              <p
                style={{
                  margin: "0 0 4px",
                  fontSize: "14px",
                  fontWeight: 600,
                  color: "#202223",
                }}
              >
                Chart limit reached
              </p>
              <p style={{ margin: 0, fontSize: "13px", color: "#6d7175" }}>
                You have reached the {plan.limits.maxCharts}-chart limit on the {plan.name}{" "}
                plan. Upgrade to Starter for unlimited charts.
              </p>
            </div>
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* TEMPLATE PICKER                                                   */}
      {/* ================================================================ */}
      {showTemplates && (
        <s-section>
          <div style={cardStyle}>
            {/* Header */}
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "6px",
              }}
            >
              <div>
                <p style={sectionTitle}>Choose a starting point</p>
                <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
                  Pick a template with pre-filled sizing data, or start from scratch.
                </p>
              </div>
              <button
                onClick={() => setShowTemplates(false)}
                style={{
                  background: "none",
                  border: "1px solid #c9cccf",
                  borderRadius: "6px",
                  cursor: "pointer",
                  padding: "4px 10px",
                  fontSize: "13px",
                  color: "#6d7175",
                  lineHeight: "20px",
                }}
                aria-label="Close template picker"
              >
                Close
              </button>
            </div>

            {/* Template grid */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))",
                gap: "10px",
                marginTop: "16px",
              }}
            >
              {templates.map((template) => (
                <div
                  key={template.name}
                  style={{
                    background: "#fff",
                    border: `1px solid ${hoveredTemplate === template.name ? "#005bd3" : "#e3e3e3"}`,
                    borderRadius: "10px",
                    padding: "14px",
                    transition: "border-color 0.15s ease",
                  }}
                  onMouseEnter={() => setHoveredTemplate(template.name)}
                  onMouseLeave={() => setHoveredTemplate(null)}
                >
                  <p
                    style={{
                      margin: "0 0 4px",
                      fontWeight: 600,
                      fontSize: "14px",
                      color: "#202223",
                    }}
                  >
                    {template.name}
                  </p>
                  <p
                    style={{
                      margin: "0 0 12px",
                      fontSize: "12px",
                      color: "#6d7175",
                    }}
                  >
                    {CATEGORY_LABELS[template.category] ?? template.category} &middot;{" "}
                    {template.gender} &middot; {template.rowCount} sizes
                  </p>
                  <fetcher.Form method="post">
                    <input type="hidden" name="intent" value="create-from-template" />
                    <input type="hidden" name="templateName" value={template.name} />
                    <s-button variant="primary" type="submit" loading={isLoading}>
                      Use Template
                    </s-button>
                  </fetcher.Form>
                </div>
              ))}

              {/* Blank chart card */}
              <div
                style={{
                  background: "#f9fafb",
                  border: `2px dashed ${hoveredTemplate === "__blank" ? "#005bd3" : "#c9cccf"}`,
                  borderRadius: "10px",
                  padding: "14px",
                  transition: "border-color 0.15s ease",
                }}
                onMouseEnter={() => setHoveredTemplate("__blank")}
                onMouseLeave={() => setHoveredTemplate(null)}
              >
                <p
                  style={{
                    margin: "0 0 4px",
                    fontWeight: 600,
                    fontSize: "14px",
                    color: "#202223",
                  }}
                >
                  Blank Chart
                </p>
                <p
                  style={{
                    margin: "0 0 12px",
                    fontSize: "12px",
                    color: "#6d7175",
                  }}
                >
                  Start from scratch with your own columns and sizes
                </p>
                <fetcher.Form method="post">
                  <input type="hidden" name="intent" value="create-blank" />
                  <input type="hidden" name="name" value="Untitled Size Chart" />
                  <input type="hidden" name="category" value="general" />
                  <s-button type="submit" loading={isLoading}>
                    Create Blank
                  </s-button>
                </fetcher.Form>
              </div>
            </div>
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* FILTER BAR                                                        */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "12px",
              flexWrap: "wrap",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <span style={{ fontSize: "13px", color: "#6d7175", whiteSpace: "nowrap" }}>
                Category
              </span>
              <select
                value={categoryFilter}
                onChange={(e) => setCategoryFilter((e.target as HTMLSelectElement).value)}
                style={{
                  border: "1px solid #c9cccf",
                  borderRadius: "8px",
                  padding: "6px 12px",
                  fontSize: "13px",
                  background: "#fff",
                  color: "#202223",
                  cursor: "pointer",
                  outline: "none",
                }}
              >
                <option value="all">All Categories</option>
                {categories.map((cat) => (
                  <option key={cat} value={cat}>
                    {CATEGORY_LABELS[cat] ?? cat}
                  </option>
                ))}
              </select>
            </div>

            <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <span style={{ fontSize: "13px", color: "#6d7175", whiteSpace: "nowrap" }}>
                Status
              </span>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter((e.target as HTMLSelectElement).value)}
                style={{
                  border: "1px solid #c9cccf",
                  borderRadius: "8px",
                  padding: "6px 12px",
                  fontSize: "13px",
                  background: "#fff",
                  color: "#202223",
                  cursor: "pointer",
                  outline: "none",
                }}
              >
                <option value="all">All Statuses</option>
                <option value="active">Active</option>
                <option value="draft">Draft</option>
              </select>
            </div>

            <span
              style={{
                marginLeft: "auto",
                fontSize: "13px",
                color: "#6d7175",
                whiteSpace: "nowrap",
              }}
            >
              {filteredCharts.length} of {charts.length} charts
            </span>
          </div>
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* CHARTS LIST                                                       */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
          {/* Section header */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "4px",
            }}
          >
            <p style={sectionTitle}>Size Charts ({charts.length})</p>
          </div>

          {/* Empty state — no charts at all */}
          {charts.length === 0 && (
            <div style={{ textAlign: "center", padding: "48px 24px" }}>
              <div
                style={{
                  width: "72px",
                  height: "72px",
                  borderRadius: "50%",
                  background: "#f0f5ff",
                  margin: "0 auto 16px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "28px",
                }}
              >
                📐
              </div>
              <p
                style={{
                  fontSize: "15px",
                  fontWeight: 600,
                  color: "#202223",
                  margin: "0 0 8px",
                }}
              >
                Create your first size chart
              </p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "0 0 20px",
                  maxWidth: "360px",
                  marginLeft: "auto",
                  marginRight: "auto",
                }}
              >
                Size charts help customers find their perfect fit and can reduce
                size-related returns by up to 40%. Get started in under 3 minutes
                using one of our pre-built templates.
              </p>
              <s-button variant="primary" onClick={() => setShowTemplates(true)}>
                Create your first chart
              </s-button>
            </div>
          )}

          {/* Empty state — filters applied */}
          {charts.length > 0 && filteredCharts.length === 0 && (
            <div style={{ textAlign: "center", padding: "40px 24px" }}>
              <p
                style={{
                  fontSize: "15px",
                  fontWeight: 600,
                  color: "#202223",
                  margin: "0 0 8px",
                }}
              >
                No charts match your filters
              </p>
              <p style={{ fontSize: "13px", color: "#6d7175", margin: "0 0 16px" }}>
                Try changing the category or status filters above.
              </p>
              <s-button
                onClick={() => {
                  setCategoryFilter("all");
                  setStatusFilter("all");
                }}
              >
                Clear filters
              </s-button>
            </div>
          )}

          {/* Chart rows */}
          {filteredCharts.length > 0 && (
            <div style={{ marginTop: "8px" }}>
              {filteredCharts.map((chart, i) => (
                <div
                  key={chart.id}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    padding: "14px 0",
                    borderBottom:
                      i === filteredCharts.length - 1
                        ? "none"
                        : "1px solid #f1f1f1",
                    gap: "16px",
                  }}
                >
                  {/* Left: name + meta */}
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ marginBottom: "6px" }}>
                      <s-link href={`/app/size-charts/${chart.id}`}>
                        <span
                          style={{
                            fontWeight: 600,
                            fontSize: "14px",
                            color: "#202223",
                          }}
                        >
                          {chart.name}
                        </span>
                      </s-link>
                    </div>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: "6px",
                        flexWrap: "wrap",
                      }}
                    >
                      <span
                        style={badgeStyle(
                          chart.status === "active" ? "success" : "neutral",
                        )}
                      >
                        {chart.status === "active" ? "Active" : "Draft"}
                      </span>
                      <span style={badgeStyle("info")}>
                        {CATEGORY_LABELS[chart.category] ?? chart.category}
                      </span>
                      <span
                        style={{
                          fontSize: "12px",
                          color: "#8c9196",
                        }}
                      >
                        {chart.assignments.length > 0
                          ? `${chart.assignments.length} product${chart.assignments.length !== 1 ? "s" : ""} assigned`
                          : "No assignments"}
                      </span>
                      <span style={{ fontSize: "12px", color: "#c9cccf" }}>&middot;</span>
                      <span style={{ fontSize: "12px", color: "#8c9196" }}>
                        Updated {formatDate(chart.updatedAt)}
                      </span>
                    </div>
                  </div>

                  {/* Right: actions */}
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "6px",
                      flexShrink: 0,
                    }}
                  >
                    <s-button href={`/app/size-charts/${chart.id}`} variant="tertiary">
                      Edit
                    </s-button>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="toggle-status" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button type="submit" loading={isLoading}>
                        {chart.status === "active" ? "Unpublish" : "Publish"}
                      </s-button>
                    </fetcher.Form>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="duplicate" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button type="submit" loading={isLoading}>
                        Duplicate
                      </s-button>
                    </fetcher.Form>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="delete" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button
                        type="submit"
                        variant="tertiary"
                        tone="critical"
                        loading={isLoading}
                      >
                        Delete
                      </s-button>
                    </fetcher.Form>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Chart Limits                                              */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Chart Limits">
        <div style={{ ...cardStyle, padding: "16px" }}>
          {/* Plan badge */}
          <div style={{ marginBottom: "12px" }}>
            <span
              style={{
                ...badgeStyle(isFreePlan ? "neutral" : "success"),
                fontSize: "12px",
              }}
            >
              {plan.name} Plan
            </span>
          </div>

          {maxCharts === -1 ? (
            <p style={{ fontSize: "13px", color: "#6d7175", margin: 0 }}>
              Unlimited charts on your plan
            </p>
          ) : (
            <>
              <p
                style={{
                  fontSize: "13px",
                  color: "#202223",
                  margin: "0 0 8px",
                  fontWeight: 600,
                }}
              >
                {publishedCount} / {maxCharts} published
              </p>
              <div
                style={{
                  height: "6px",
                  background: "#e4e5e7",
                  borderRadius: "3px",
                  overflow: "hidden",
                  marginBottom: "4px",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${progressPct}%`,
                    background: progressColor,
                    borderRadius: "3px",
                    transition: "width 0.3s ease",
                  }}
                />
              </div>
              <p style={{ fontSize: "12px", color: "#8c9196", margin: "0 0 14px" }}>
                {maxCharts - publishedCount > 0
                  ? `${maxCharts - publishedCount} slot${maxCharts - publishedCount !== 1 ? "s" : ""} remaining`
                  : "Limit reached"}
              </p>

              <s-button href="/app/pricing" variant="primary">
                Upgrade for unlimited
              </s-button>
            </>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick Tips                                                */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick Tips">
        <s-unordered-list>
          <s-list-item>
            Assign charts to products or collections for automatic display in your
            storefront widget
          </s-list-item>
          <s-list-item>
            Use templates — they include standard sizing data to get you started fast
          </s-list-item>
          <s-list-item>
            Publish a chart to make it visible to customers
          </s-list-item>
          <s-list-item>
            Add both inch and centimeter values for international customers
          </s-list-item>
        </s-unordered-list>
      </s-section>
    </s-page>
  );
}

