      >
        <span
          style={{
            fontWeight: 700,
            fontSize: "13px",
            color: "#ffffff",
            letterSpacing: "0.01em",
          }}
        >
          {name || "Size Chart"}
        </span>
        <div style={{ display: "flex", gap: "4px", alignItems: "center" }}>
          <div
            style={{
              width: "6px",
              height: "6px",
              borderRadius: "50%",
              background: status === "active" ? "#24c57b" : "#8c9196",
