        </div>
      </div>

      {/* Unit tab strip */}
      <div
        style={{
          background: "#f6f6f7",
          borderBottom: "1px solid #e1e3e5",
          padding: "6px 16px",
          display: "flex",
          gap: "4px",
        }}
      >
        {data.units.available.map((unit) => (
          <span
            key={unit}
            style={{
              padding: "2px 10px",
              borderRadius: "12px",
              fontSize: "11px",
              fontWeight: 600,
              background:
                unit === data.units.default ? "#202223" : "transparent",
              color:
                unit === data.units.default ? "#ffffff" : "#8c9196",
              cursor: "default",
            }}
          >
            {unit}
          </span>
        ))}
      </div>

      {/* Preview table */}
      <div style={{ overflowX: "auto" }}>
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "12px",
          }}
        >
          <thead>
            <tr>
              {data.headers.map((h, i) => (
                <th
                  key={i}
                  style={{
                    background: "#f6f6f7",
                    padding: "8px 12px",
                    textAlign: "left",
                    fontWeight: 700,
                    fontSize: "11px",
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                    color: "#6d7175",
                    borderBottom: "1px solid #e1e3e5",
                    borderRight:
                      i < data.headers.length - 1
                        ? "1px solid #e1e3e5"
                        : "none",
                    whiteSpace: "nowrap",
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                style={{ background: ri % 2 === 0 ? "#fff" : "#fafbfb" }}
              >
                {data.headers.map((h, hi) => (
                  <td
                    key={hi}
                    style={{
                      padding: "8px 12px",
                      borderBottom:
                        ri < data.rows.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      borderRight:
                        hi < data.headers.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      color: row[h] ? "#202223" : "#c9cccf",
                      fontWeight: hi === 0 ? 600 : 400,
                    }}
                  >
                    {row[h] || "—"}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Footer */}
      <div
        style={{
          padding: "8px 16px",
          background: "#f6f6f7",
          borderTop: "1px solid #e1e3e5",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <span style={{ fontSize: "11px", color: "#8c9196" }}>
          Measurements in {data.units.default}
        </span>
        <span style={{ fontSize: "11px", color: "#8c9196", fontWeight: 600 }}>
          {data.rows.length} sizes
        </span>
      </div>
    </div>
  );
}

