 995→type LoaderData = Awaited<ReturnType<typeof loader>>;
 996→
 997→export default function SizeChartEditor() {
 998→  const loaderData = useLoaderData<typeof loader>() as LoaderData;
 999→  const { chart, assignments: initialAssignments, isNew } = loaderData;
1000→
1001→  const saveFetcher = useFetcher<typeof action>();
1002→  const statusFetcher = useFetcher<typeof action>();
1003→  const assignmentFetcher = useFetcher<typeof action>();
1004→  const shopify = useAppBridge();
1005→
1006→  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
1007→  const [category, setCategory] = useState(chart?.category ?? "general");
1008→  const [status, setStatus] = useState(chart?.status ?? "draft");
1009→  const [chartData, setChartData] = useState<ChartData>(
1010→    chart ? parseChartData(chart.data) : makeDefaultData(),
1011→  );
1012→  const [assignments, setAssignments] =
1013→    useState<Assignment[]>(initialAssignments);
1014→  const [newAssignmentType, setNewAssignmentType] = useState("product");
1015→  const [newAssignmentValue, setNewAssignmentValue] = useState("");
1016→
1017→  const isSaving = saveFetcher.state !== "idle";
1018→  const isTogglingStatus = statusFetcher.state !== "idle";
1019→
1020→  // Check for ?saved=1 on mount (after redirect from new chart creation)
1021→  useEffect(() => {
1022→    if (typeof window !== "undefined") {
1023→      const url = new URL(window.location.href);
1024→      if (url.searchParams.get("saved") === "1") {
1025→        shopify.toast.show("Chart created successfully");
1026→        url.searchParams.delete("saved");
1027→        window.history.replaceState({}, "", url.toString());
1028→      }
1029→    }
1030→  }, [shopify]);
1031→
1032→  // Save feedback
1033→  useEffect(() => {
1034→    if (!saveFetcher.data) return;
1035→    const data = saveFetcher.data;
1036→    if ("ok" in data && data.ok) {
1037→      shopify.toast.show(data.message ?? "Saved");
1038→    } else if ("error" in data) {
1039→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
1040→    }
1041→  }, [saveFetcher.data, shopify]);
1042→
1043→  // Status toggle feedback
1044→  useEffect(() => {
1045→    if (!statusFetcher.data) return;
1046→    const data = statusFetcher.data;
