              justifyContent: "space-between",
              gap: "16px",
            }}
          >
            <div style={{ display: "flex", alignItems: "flex-start", gap: "12px" }}>
              <span style={{ fontSize: "20px", flexShrink: 0, marginTop: "1px" }}>
                ⚠️
              </span>
              <div>
                <p
                  style={{
                    margin: "0 0 4px",
                    fontSize: "14px",
                    fontWeight: 600,
                    color: "#202223",
                  }}
                >
                  Chart limit reached
