      {/* CHARTS LIST                                                       */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
          {/* Section header */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: charts.length > 0 ? "4px" : "0",
