          <thead>
            <tr>
              {data.headers.map((header, hi) => (
                <th
                  key={hi}
                  style={{
                    background: "#f6f6f7",
                    borderBottom: "2px solid #e1e3e5",
                    borderRight:
                      hi < data.headers.length - 1
                        ? "1px solid #e1e3e5"
                        : "none",
                    padding: "0",
                    position: "relative",
                    minWidth: "110px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      padding: "2px 6px 2px 10px",
                    }}
                  >
                    <input
                      ref={(el) => {
                        headerInputRefs.current[hi] = el;
                      }}
                      value={header}
                      onChange={(e) =>
                        updateHeader(hi, (e.target as HTMLInputElement).value)
                      }
                      style={{
                        flex: 1,
                        border: "none",
                        background: "transparent",
                        fontWeight: 700,
                        fontSize: "12px",
                        color: "#202223",
                        padding: "8px 4px",
                        outline: "none",
                        minWidth: "60px",
                        textTransform: "uppercase",
                        letterSpacing: "0.04em",
                        fontFamily: "inherit",
                      }}
                      placeholder={`Col ${hi + 1}`}
                    />
                    {data.headers.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeColumn(hi)}
                        title="Remove column"
                        style={{
                          background: "none",
                          border: "none",
                          cursor: "pointer",
                          color: "#c9cccf",
                          padding: "2px 4px",
                          borderRadius: "4px",
                          fontSize: "15px",
                          lineHeight: 1,
                          flexShrink: 0,
                          transition: "color 0.1s, background 0.1s",
                          fontFamily: "inherit",
                        }}
                        onMouseEnter={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
                            "#d82c0d";
                          (
                            e.currentTarget as HTMLButtonElement
                          ).style.background = "#fee2e2";
                        }}
                        onMouseLeave={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
                            "#c9cccf";
                          (
                            e.currentTarget as HTMLButtonElement
                          ).style.background = "none";
                        }}
                      >
                        &times;
                      </button>
                    )}
                  </div>
                </th>
              ))}

              {/* Add column header cell */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  padding: "0",
                  width: "40px",
                  minWidth: "40px",
                }}
              >
                <button
                  type="button"
                  onClick={addColumn}
                  title="Add column"
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "100%",
                    height: "100%",
                    minHeight: "38px",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "20px",
                    lineHeight: 1,
                    padding: "0",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  +
                </button>
              </th>

              {/* Row actions header spacer */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  width: "36px",
                  minWidth: "36px",
                }}
              />
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                style={{
                  background: ri % 2 === 0 ? "#ffffff" : "#fafbfb",
                  transition: "background 0.1s",
                }}
                onMouseEnter={(e) => {
                  (e.currentTarget as HTMLTableRowElement).style.background =
                    "#f0f5ff";
                }}
                onMouseLeave={(e) => {
                  (e.currentTarget as HTMLTableRowElement).style.background =
                    ri % 2 === 0 ? "#ffffff" : "#fafbfb";
                }}
              >
                {data.headers.map((header, hi) => (
                  <td
                    key={hi}
                    style={{
                      borderBottom:
                        ri < data.rows.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      borderRight:
                        hi < data.headers.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      padding: "0",
                    }}
                  >
                    <input
                      value={row[header] ?? ""}
                      onChange={(e) =>
                        updateCell(
                          ri,
                          header,
                          (e.target as HTMLInputElement).value,
                        )
                      }
                      style={{
                        width: "100%",
                        border: "none",
                        background: "transparent",
                        padding: "9px 10px",
                        fontSize: "13px",
                        color: "#202223",
                        outline: "none",
                        boxSizing: "border-box",
                        fontFamily: "inherit",
                      }}
                      onFocus={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow =
                          "inset 0 0 0 2px #2c6ecb";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "#f0f5ff";
                      }}
                      onBlur={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow = "none";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "transparent";
                      }}
                      placeholder="—"
                    />
                  </td>
                ))}

                {/* Column spacer — aligns under add column button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    borderRight: "1px solid #e1e3e5",
                    width: "40px",
                    background: "transparent",
                  }}
                />

                {/* Remove row button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    padding: "0",
                    textAlign: "center",
                    width: "36px",
                    background: "transparent",
                  }}
                >
                  <button
                    type="button"
                    onClick={() => removeRow(ri)}
                    title="Remove row"
                    style={{
                      background: "none",
                      border: "none",
                      cursor: "pointer",
                      color: "#c9cccf",
                      fontSize: "16px",
                      lineHeight: 1,
                      padding: "4px 8px",
                      borderRadius: "4px",
                      transition: "color 0.1s, background 0.1s",
                      fontFamily: "inherit",
                    }}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#d82c0d";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "#fee2e2";
                    }}
                    onMouseLeave={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#c9cccf";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "none";
                    }}
                  >
                    &times;
                  </button>
                </td>
              </tr>
            ))}

            {/* Add row footer */}
            <tr>
              <td
                colSpan={data.headers.length + 2}
                style={{
                  padding: "0",
                  background: "#f6f6f7",
                  borderTop: "1px solid #e1e3e5",
                }}
              >
                <button
                  type="button"
                  onClick={addRow}
                  style={{
                    display: "block",
                    width: "100%",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "13px",
                    fontWeight: 600,
                    padding: "10px 14px",
                    textAlign: "left",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  + Add row
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

