     8→// ---------------------------------------------------------------------------
     9→// Types
    10→// ---------------------------------------------------------------------------
    11→
    12→interface ChartData {
    13→  headers: string[];
    14→  units: { default: string; available: string[] };
    15→  rows: Record<string, string>[];
    16→}
    17→
    18→interface Assignment {
    19→  id: string;
    20→  assignmentType: string;
    21→  assignmentValue: string;
