            >
              Tip: Use a soft measuring tape and measure directly on the skin
              or over light clothing for the most accurate fit.
            </p>
          </div>
        </div>

        {/* Danger Zone card */}
        {!isNew && (
          <div
            style={{
              background: "#fff8f8",
              border: "1px solid #fcd4d1",
              borderRadius: "12px",
              padding: "20px",
            }}
          >
            <p
              style={{
                margin: "0 0 4px",
                fontSize: "15px",
                fontWeight: 650,
                color: "#d82c0d",
              }}
            >
              Danger Zone
            </p>
            <p
              style={{
                margin: "0 0 16px",
                fontSize: "13px",
                color: "#6d7175",
                lineHeight: 1.5,
              }}
            >
              Permanently deletes this chart and all its product assignments.
              This action cannot be undone.
            </p>
            <assignmentFetcher.Form method="post">
              <input type="hidden" name="intent" value="delete" />
              <button
                type="submit"
                style={{
                  background: "#d82c0d",
                  border: "none",
                  borderRadius: "8px",
                  padding: "8px 16px",
                  fontSize: "13px",
                  fontWeight: 600,
                  color: "#fff",
                  cursor: "pointer",
                  fontFamily: "inherit",
                  transition: "background 0.1s",
                }}
                onMouseEnter={(e) => {
