          {[
            { label: "Created", value: formatDate(chart.createdAt) },
            { label: "Last updated", value: formatDate(chart.updatedAt) },
            { label: "Assignments", value: String(assignments.length) },
            { label: "Sizes (rows)", value: String(chartData.rows.length) },
            { label: "Columns", value: String(chartData.headers.length) },
          ].map((item, idx, arr) => (
            <div
              key={item.label}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "baseline",
                padding: "8px 0",
                borderBottom:
                  idx < arr.length - 1 ? "1px solid #f1f1f1" : "none",
              }}
            >
              <span
                style={{
                  fontSize: "12px",
                  color: "#8c9196",
                  fontWeight: 500,
                }}
              >
                {item.label}
              </span>
              <span
                style={{
                  fontSize: "13px",
                  color: "#202223",
                  fontWeight: 600,
                  textAlign: "right",
                  maxWidth: "55%",
                }}
              >
                {item.value}
              </span>
            </div>
          ))}
        </div>
      </s-section>
    )}
  </s-page>
);

