type LoaderData = Awaited<ReturnType<typeof loader>>;
type ActiveTab = "chart" | "assignments" | "position" | "recommendation" | "settings";

export default function SizeChartEditor() {
  const loaderData = useLoaderData<typeof loader>() as LoaderData;
  const { chart, assignments: initialAssignments, isNew } = loaderData;

  const saveFetcher = useFetcher<typeof action>();
  const statusFetcher = useFetcher<typeof action>();
  const assignmentFetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
  const [category, setCategory] = useState(chart?.category ?? "general");
  const [status, setStatus] = useState(chart?.status ?? "draft");
  const [chartData, setChartData] = useState<ChartData>(
    chart ? parseChartData(chart.data) : makeDefaultData(),
  );
  const [assignments, setAssignments] =
    useState<Assignment[]>(initialAssignments);
  const [newAssignmentType, setNewAssignmentType] = useState("product");
  const [newAssignmentValue, setNewAssignmentValue] = useState("");

  // Position settings (stored in chartData.displaySettings)
  const _parsedSettings = chart ? parseChartData(chart.data).displaySettings : undefined;
  const [priority, setPriority] = useState(_parsedSettings?.priority ?? 1);
  const [countries, setCountries] = useState<"all" | "selected">(_parsedSettings?.countries ?? "all");
  const [selectedCountries, setSelectedCountries] = useState(_parsedSettings?.selectedCountries ?? "");
  const [buttonPosition, setButtonPosition] = useState<"floating" | "above_desc" | "below_desc">(_parsedSettings?.buttonPosition ?? "floating");
  const [recommendationEnabled, setRecommendationEnabled] = useState(
    chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
  );

  const isSaving = saveFetcher.state !== "idle";
  const isTogglingStatus = statusFetcher.state !== "idle";

  // Check for ?saved=1 on mount (after redirect from new chart creation)
  useEffect(() => {
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      if (url.searchParams.get("saved") === "1") {
        shopify.toast.show("Chart created successfully");
        url.searchParams.delete("saved");
        window.history.replaceState({}, "", url.toString());
      }
    }
  }, [shopify]);

  // Save feedback
  useEffect(() => {
    if (!saveFetcher.data) return;
    const data = saveFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Saved");
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [saveFetcher.data, shopify]);

  // Status toggle feedback
  useEffect(() => {
    if (!statusFetcher.data) return;
    const data = statusFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Status updated");
      if ("newStatus" in data && typeof data.newStatus === "string") {
        setStatus(data.newStatus);
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [statusFetcher.data, shopify]);

  // Assignment feedback
  useEffect(() => {
    if (!assignmentFetcher.data) return;
    const data = assignmentFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Done");
      setNewAssignmentValue("");
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [assignmentFetcher.data, shopify]);

  const handleSave = () => {
    const formData = new FormData();
    formData.set("intent", "save");
    formData.set("name", name);
    formData.set("category", category);
    formData.set("status", status);
    const fullData: ChartData = {
      ...chartData,
      displaySettings: { priority, countries, selectedCountries, buttonPosition },
      recommendationEnabled,
    };
    formData.set("data", JSON.stringify(fullData));
    saveFetcher.submit(formData, { method: "post" });
  };

  const handleToggleStatus = () => {
    const formData = new FormData();
    formData.set("intent", "toggle-status");
    statusFetcher.submit(formData, { method: "post" });
  };

  const handleAddAssignment = () => {
    if (!newAssignmentValue.trim() && newAssignmentType !== "all") return;
    const formData = new FormData();
    formData.set("intent", "add-assignment");
    formData.set("assignmentType", newAssignmentType);
    formData.set(
      "assignmentValue",
      newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
    );
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => [
      ...prev,
      {
        id: `temp-${Date.now()}`,
        assignmentType: newAssignmentType,
        assignmentValue:
          newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
      },
    ]);
  };

  const handleRemoveAssignment = (assignmentId: string) => {
    const formData = new FormData();
    formData.set("intent", "remove-assignment");
    formData.set("assignmentId", assignmentId);
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => prev.filter((a) => a.id !== assignmentId));
  };

  const assignmentTypeLabel = (type: string) =>
    ASSIGNMENT_TYPES.find((t) => t.value === type)?.label ?? type;

  return (
    <s-page
      heading={isNew ? "New Size Chart" : name}
      back-action-url="/app/size-charts"
    >
      <s-button
        slot="primary-action"
        variant="primary"
        onClick={handleSave}
        loading={isSaving}
        disabled={isSaving}
      >
        {isSaving ? "Saving..." : "Save"}
      </s-button>

      <s-button
        slot="secondary-action"
        onClick={handleToggleStatus}
        loading={isTogglingStatus}
        disabled={isNew || isTogglingStatus}
      >
        {status === "active" ? "Unpublish" : "Publish"}
      </s-button>

      {/* ================================================================ */}
      {/* Tab navigation                                                     */}
      {/* ================================================================ */}
      <s-section>
        <div
          style={{
            display: "flex",
            gap: "0",
            borderBottom: "1px solid #e1e3e5",
            marginBottom: "4px",
          }}
        >
          {(
            [
              { id: "chart" as const, label: "Size Chart" },
              { id: "assignments" as const, label: "Assignments" },
              { id: "settings" as const, label: "Settings" },
            ] satisfies { id: ActiveTab; label: string }[]
          ).map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setActiveTab(tab.id)}
              style={tabStyle(activeTab === tab.id)}
            >
              {tab.label}
              {tab.id === "assignments" && assignments.length > 0 && (
                <span
                  style={{
                    marginLeft: "6px",
                    background:
                      activeTab === "assignments" ? "#202223" : "#e4e5e7",
                    color:
                      activeTab === "assignments" ? "#ffffff" : "#6d7175",
                    borderRadius: "10px",
                    fontSize: "11px",
                    fontWeight: 700,
                    padding: "1px 6px",
                    lineHeight: "16px",
                    display: "inline-block",
                    verticalAlign: "middle",
                  }}
                >
                  {assignments.length}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* ============================================================== */}
        {/* TAB: Size Chart                                                 */}
        {/* ============================================================== */}
        <div style={{ display: activeTab === "chart" ? "block" : "none" }}>
          {/* General Settings card */}
          <div style={{ ...cardStyle, marginBottom: "16px" }}>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                marginBottom: "16px",
              }}
            >
              <p style={sectionTitle}>General Settings</p>
              <span
                style={badgeStyle(status === "active" ? "success" : "neutral")}
              >
                {status === "active" ? "Published" : "Draft"}
              </span>
            </div>

            {/* Name field */}
            <div style={{ marginBottom: "16px" }}>
              <label style={labelStyle} htmlFor="chart-name">
                Chart name
              </label>
              <input
                id="chart-name"
                value={name}
                onChange={(e) => setName((e.target as HTMLInputElement).value)}
                placeholder="e.g. Women's Tops Size Chart"
                style={inputStyle}
                onFocus={(e) => focusInput(e.target as HTMLInputElement)}
                onBlur={(e) => blurInput(e.target as HTMLInputElement)}
              />
            </div>

            {/* Category + Status row */}
            <div
              style={{ display: "flex", gap: "16px", alignItems: "flex-end" }}
            >
              <div style={{ flex: 1 }}>
                <label style={labelStyle} htmlFor="chart-category">
                  Category
                </label>
                <select
                  id="chart-category"
                  value={category}
                  onChange={(e) =>
                    setCategory((e.target as HTMLSelectElement).value)
                  }
                  style={{
                    ...inputStyle,
                    cursor: "pointer",
                    appearance: "auto",
                  }}
                  onFocus={(e) => focusInput(e.target as HTMLSelectElement)}
                  onBlur={(e) => blurInput(e.target as HTMLSelectElement)}
                >
                  {CATEGORIES.map((c) => (
                    <option key={c.value} value={c.value}>
                      {c.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ ...labelStyle, color: "#6d7175" }}>
                  Status
                </label>
                <div style={{ paddingBottom: "9px" }}>
                  <span
                    style={{
                      ...badgeStyle(
                        status === "active" ? "success" : "neutral",
                      ),
                      fontSize: "12px",
                      padding: "4px 10px",
                    }}
                  >
                    {status === "active" ? "Published" : "Draft"}
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Size Table card */}
          <div style={cardStyle}>
            <div style={{ marginBottom: "14px" }}>
              <p style={sectionTitle}>Size Table</p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "4px 0 0",
                }}
              >
                Click any cell to edit. Click a column header to rename it. Use
                the + buttons to add rows or columns.
              </p>
            </div>
            <TableEditor data={chartData} onChange={setChartData} />
          </div>
        </div>

        {/* ============================================================== */}
        {/* TAB: Assignments                                                */}
        {/* ============================================================== */}
        <div
          style={{ display: activeTab === "assignments" ? "block" : "none" }}
        >
          {/* Current Assignments card */}
          <div style={{ ...cardStyle, marginBottom: "16px" }}>
            <div style={{ marginBottom: "16px" }}>
              <p style={sectionTitle}>Current Assignments</p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "4px 0 0",
                }}
              >
                This chart will appear on matching product pages.
              </p>
            </div>

            {/* New chart info banner */}
            {isNew && (
              <div
                style={{
                  background: "#e8f0fe",
                  border: "1px solid #c5d8f6",
                  borderRadius: "8px",
                  padding: "12px 14px",
                  display: "flex",
                  alignItems: "flex-start",
                  gap: "10px",
                }}
              >
                <span
                  style={{
                    fontSize: "16px",
                    lineHeight: 1,
                    marginTop: "1px",
                  }}
                >
                  &#9432;
                </span>
                <p
                  style={{
                    margin: 0,
                    fontSize: "13px",
                    color: "#3b3f8c",
                    fontWeight: 500,
                  }}
                >
                  Save the chart first to add product assignments.
                </p>
              </div>
            )}

            {/* Existing assignments list */}
            {assignments.length > 0 && (
              <div
                style={{
                  border: "1px solid #e3e3e3",
                  borderRadius: "8px",
                  overflow: "hidden",
                }}
              >
                {assignments.map((assignment, i) => (
                  <div
                    key={assignment.id}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "12px",
                      padding: "11px 14px",
                      background: i % 2 === 0 ? "#ffffff" : "#fafbfb",
                      borderBottom:
                        i < assignments.length - 1
                          ? "1px solid #e3e3e3"
                          : "none",
                    }}
                  >
                    <span style={badgeStyle("info")}>
                      {assignmentTypeLabel(assignment.assignmentType)}
                    </span>
                    <span
                      style={{
                        flex: 1,
                        fontSize: "13px",
                        color: "#202223",
                        fontWeight: 500,
                        fontFamily: "monospace",
                      }}
                    >
                      {assignment.assignmentValue === "*"
                        ? "All products"
                        : assignment.assignmentValue}
                    </span>
                    <button
                      type="button"
                      onClick={() => handleRemoveAssignment(assignment.id)}
                      style={{
                        background: "none",
                        border: "none",
                        cursor: "pointer",
                        color: "#8c9196",
                        fontSize: "12px",
                        fontWeight: 600,
                        padding: "4px 8px",
                        borderRadius: "4px",
                        transition: "color 0.1s, background 0.1s",
                        fontFamily: "inherit",
                      }}
                      onMouseEnter={(e) => {
                        (e.currentTarget as HTMLButtonElement).style.color =
                          "#d82c0d";
                        (
                          e.currentTarget as HTMLButtonElement
                        ).style.background = "#fee2e2";
                      }}
                      onMouseLeave={(e) => {
                        (e.currentTarget as HTMLButtonElement).style.color =
                          "#8c9196";
                        (
                          e.currentTarget as HTMLButtonElement
                        ).style.background = "none";
                      }}
                    >
                      Remove
                    </button>
                  </div>
                ))}
              </div>
            )}

            {/* Empty state */}
            {assignments.length === 0 && !isNew && (
              <div
                style={{
                  border: "1.5px dashed #c9cccf",
                  borderRadius: "8px",
                  padding: "28px 16px",
                  textAlign: "center",
                  background: "#fafbfb",
                }}
              >
                <div
                  style={{
                    fontSize: "28px",
                    marginBottom: "8px",
                    lineHeight: 1,
                  }}
                >
                  &#128205;
                </div>
                <p
                  style={{
                    margin: 0,
                    fontSize: "14px",
                    color: "#202223",
                    fontWeight: 600,
                  }}
                >
                  No assignments yet
                </p>
                <p
                  style={{
                    margin: "4px 0 0",
                    fontSize: "13px",
                    color: "#8c9196",
                  }}
                >
                  Add an assignment below to show this chart on product pages.
                </p>
              </div>
            )}
          </div>

          {/* Add Assignment card */}
          {!isNew && (
            <div style={cardStyle}>
              <div style={{ marginBottom: "14px" }}>
                <p style={sectionTitle}>Add Assignment</p>
                <p
                  style={{
                    fontSize: "13px",
                    color: "#6d7175",
                    margin: "4px 0 0",
                  }}
                >
                  Target by product, collection, tag, or product type.
                </p>
              </div>

              <div
                style={{
                  display: "flex",
                  gap: "10px",
                  alignItems: "flex-end",
                }}
              >
                {/* Type select */}
                <div style={{ flexShrink: 0 }}>
                  <label style={labelStyle} htmlFor="assignment-type">
                    Type
                  </label>
                  <select
                    id="assignment-type"
                    value={newAssignmentType}
                    onChange={(e) =>
                      setNewAssignmentType(
                        (e.target as HTMLSelectElement).value,
                      )
                    }
                    style={{
                      border: "1px solid #c9cccf",
                      borderRadius: "8px",
                      padding: "8px 10px",
                      fontSize: "13px",
                      background: "#fff",
                      cursor: "pointer",
                      outline: "none",
                      fontFamily: "inherit",
                      color: "#202223",
                    }}
                    onFocus={(e) => focusInput(e.target as HTMLSelectElement)}
                    onBlur={(e) => blurInput(e.target as HTMLSelectElement)}
                  >
                    {ASSIGNMENT_TYPES.map((t) => (
                      <option key={t.value} value={t.value}>
                        {t.label}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Value input — hidden for "all" type */}
                {newAssignmentType !== "all" && (
                  <div style={{ flex: 1 }}>
                    <label style={labelStyle} htmlFor="assignment-value">
                      Value
                    </label>
                    <input
                      id="assignment-value"
                      value={newAssignmentValue}
                      onChange={(e) =>
                        setNewAssignmentValue(
                          (e.target as HTMLInputElement).value,
                        )
                      }
                      placeholder={
                        newAssignmentType === "tag"
                          ? "e.g. summer-sale"
                          : newAssignmentType === "product_type"
                            ? "e.g. T-Shirts"
                            : newAssignmentType === "collection"
                              ? "e.g. gid://shopify/Collection/123"
                              : "e.g. gid://shopify/Product/123"
                      }
                      style={inputStyle}
                      onFocus={(e) => focusInput(e.target as HTMLInputElement)}
                      onBlur={(e) => blurInput(e.target as HTMLInputElement)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          handleAddAssignment();
                        }
                      }}
                    />
                  </div>
                )}

                <div style={{ flexShrink: 0, paddingBottom: "1px" }}>
                  <s-button
                    variant="primary"
                    onClick={handleAddAssignment}
                    loading={assignmentFetcher.state !== "idle"}
                  >
                    Add
                  </s-button>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* ============================================================== */}
        {/* TAB: Settings                                                   */}
        {/* ============================================================== */}
        <div style={{ display: activeTab === "settings" ? "block" : "none" }}>
          {/* How to Measure card */}
          <div style={{ ...cardStyle, marginBottom: "16px" }}>
            <div style={{ marginBottom: "14px" }}>
              <p style={sectionTitle}>How to Measure</p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "4px 0 0",
                }}
              >
                This guide is shown alongside your size chart to help customers
                measure correctly.
              </p>
            </div>
            <div
              style={{
                background: "#f9fafb",
                border: "1px solid #e1e3e5",
                borderRadius: "8px",
                padding: "16px 18px",
              }}
            >
              <p
                style={{
                  margin: "0 0 10px",
                  fontSize: "13px",
                  fontWeight: 700,
                  color: "#202223",
                }}
              >
                Measurement Instructions
              </p>
              <ul
                style={{
                  margin: 0,
                  padding: "0 0 0 18px",
                  listStyleType: "disc",
                }}
              >
                {[
                  {
                    label: "Chest",
                    desc: "Measure around the fullest part of your chest, keeping the tape parallel to the floor.",
                  },
                  {
                    label: "Waist",
                    desc: "Measure around the narrowest part of your waist, typically 1 inch above the navel.",
                  },
                  {
                    label: "Hips",
                    desc: "Measure around the fullest part of your hips, approximately 8 inches below the waist.",
                  },
                  {
                    label: "Inseam",
                    desc: "Measure from the crotch seam down to the ankle bone along the inside of the leg.",
                  },
                ].map((item) => (
                  <li
                    key={item.label}
                    style={{
                      fontSize: "13px",
                      color: "#202223",
                      lineHeight: 1.6,
                      marginBottom: "6px",
                    }}
                  >
                    <strong style={{ color: "#202223" }}>{item.label}:</strong>{" "}
                    <span style={{ color: "#6d7175" }}>{item.desc}</span>
                  </li>
                ))}
              </ul>
              <p
                style={{
                  margin: "12px 0 0",
                  fontSize: "12px",
                  color: "#8c9196",
                  fontStyle: "italic",
                }}
              >
                Tip: Use a soft measuring tape and measure directly on the skin
                or over light clothing for the most accurate fit.
              </p>
            </div>
          </div>

          {/* Danger Zone card */}
          {!isNew && (
            <div
              style={{
                background: "#fff8f8",
                border: "1px solid #fcd4d1",
                borderRadius: "12px",
                padding: "20px",
              }}
            >
              <p
                style={{
                  margin: "0 0 4px",
                  fontSize: "15px",
                  fontWeight: 650,
                  color: "#d82c0d",
                }}
              >
                Danger Zone
              </p>
              <p
                style={{
                  margin: "0 0 16px",
                  fontSize: "13px",
                  color: "#6d7175",
                  lineHeight: 1.5,
                }}
              >
                Permanently deletes this chart and all its product assignments.
                This action cannot be undone.
              </p>
              <assignmentFetcher.Form method="post">
                <input type="hidden" name="intent" value="delete" />
                <button
                  type="submit"
                  style={{
                    background: "#d82c0d",
                    border: "none",
                    borderRadius: "8px",
                    padding: "8px 16px",
                    fontSize: "13px",
                    fontWeight: 600,
                    color: "#fff",
                    cursor: "pointer",
                    fontFamily: "inherit",
                    transition: "background 0.1s",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#b52b0c";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#d82c0d";
                  }}
                >
                  Delete Chart Permanently
                </button>
              </assignmentFetcher.Form>
            </div>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Live Widget Preview (always visible)                       */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Widget Preview">
        <ChartPreview data={chartData} name={name} status={status} />
        <p
          style={{
            fontSize: "12px",
            color: "#8c9196",
            marginTop: "10px",
            marginBottom: 0,
            textAlign: "center",
          }}
        >
          Live preview — reflects your edits instantly.
        </p>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Chart Info (always visible for saved charts)              */}
      {/* ================================================================ */}
      {!isNew && chart && (
        <s-section slot="aside" heading="Chart Info">
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "0",
            }}
          >
            {[
              { label: "Created", value: formatDate(chart.createdAt) },
              { label: "Last updated", value: formatDate(chart.updatedAt) },
              { label: "Assignments", value: String(assignments.length) },
              { label: "Sizes (rows)", value: String(chartData.rows.length) },
              { label: "Columns", value: String(chartData.headers.length) },
            ].map((item, idx, arr) => (
              <div
                key={item.label}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "baseline",
                  padding: "8px 0",
                  borderBottom:
                    idx < arr.length - 1 ? "1px solid #f1f1f1" : "none",
                }}
              >
                <span
                  style={{
                    fontSize: "12px",
                    color: "#8c9196",
                    fontWeight: 500,
                  }}
                >
                  {item.label}
                </span>
                <span
                  style={{
                    fontSize: "13px",
                    color: "#202223",
                    fontWeight: 600,
                    textAlign: "right",
                    maxWidth: "55%",
                  }}
                >
                  {item.value}
                </span>
              </div>
            ))}
          </div>
        </s-section>
      )}
    </s-page>
  );
}

input.new_string:
{/* ============================================================== */}
{/* TAB: Position                                                   */}
{/* ============================================================== */}
<div style={{ display: activeTab === "position" ? "block" : "none" }}>
  {/* Priority card */}
  <div style={{ ...cardStyle, marginBottom: "16px" }}>
    <div style={{ marginBottom: "16px" }}>
      <p style={sectionTitle}>Display Priority</p>
      <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
        When multiple charts match a product, the one with the lowest priority number is shown first.
      </p>
    </div>
    <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
      <label style={labelStyle} htmlFor="chart-priority">Priority level</label>
      <input
        id="chart-priority"
        type="number"
        min={1}
        max={100}
        value={priority}
        onChange={(e) => setPriority(Math.max(1, Math.min(100, parseInt((e.target as HTMLInputElement).value, 10) || 1)))}
        style={{ ...inputStyle, width: "80px", textAlign: "center" }}
        onFocus={(e) => focusInput(e.target as HTMLInputElement)}
        onBlur={(e) => blurInput(e.target as HTMLInputElement)}
      />
      <span style={{ fontSize: "13px", color: "#6d7175" }}>
        {priority === 1 ? "Highest priority" : priority <= 5 ? "High priority" : priority <= 20 ? "Medium priority" : "Low priority"}
      </span>
    </div>
  </div>

  {/* Display Position card */}
  <div style={{ ...cardStyle, marginBottom: "16px" }}>
    <div style={{ marginBottom: "16px" }}>
      <p style={sectionTitle}>Widget Button Position</p>
      <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
        Choose where the "Size Guide" button appears on your product pages.
      </p>
    </div>
    <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
      {(
        [
          { value: "floating" as const, label: "Floating button", desc: "A floating button appears near the size selector — highest visibility" },
          { value: "above_desc" as const, label: "Above description", desc: "Shown above the product description section" },
          { value: "below_desc" as const, label: "Below description", desc: "Shown below the product description section" },
        ] satisfies { value: "floating" | "above_desc" | "below_desc"; label: string; desc: string }[]
      ).map((opt) => (
        <label
          key={opt.value}
          style={{
            display: "flex",
            alignItems: "flex-start",
            gap: "12px",
            padding: "12px 14px",
            border: `1.5px solid ${buttonPosition === opt.value ? "#2c6ecb" : "#e3e3e3"}`,
            borderRadius: "8px",
            background: buttonPosition === opt.value ? "#f0f5ff" : "#fff",
            cursor: "pointer",
            transition: "all 0.12s ease",
          }}
        >
          <input
            type="radio"
            name="buttonPosition"
            value={opt.value}
            checked={buttonPosition === opt.value}
            onChange={() => setButtonPosition(opt.value)}
            style={{ marginTop: "2px", accentColor: "#2c6ecb", flexShrink: 0 }}
          />
          <div>
            <p style={{ margin: "0 0 2px", fontSize: "14px", fontWeight: 600, color: "#202223" }}>{opt.label}</p>
            <p style={{ margin: 0, fontSize: "12px", color: "#6d7175" }}>{opt.desc}</p>
          </div>
        </label>
      ))}
    </div>
  </div>

  {/* Country Targeting card */}
  <div style={cardStyle}>
    <div style={{ marginBottom: "16px" }}>
      <p style={sectionTitle}>Country Targeting</p>
      <p style={{ fontSize: "13px", color: "#6d7175", margin: "4px 0 0" }}>
        Limit this chart to customers in specific countries (e.g. show EU sizing only in Europe).
      </p>
    </div>
    <div style={{ display: "flex", flexDirection: "column", gap: "10px", marginBottom: countries === "selected" ? "14px" : "0" }}>
      {(
        [
          { value: "all" as const, label: "All countries", desc: "Show this chart to all visitors regardless of location" },
          { value: "selected" as const, label: "Specific countries", desc: "Restrict to selected country codes (e.g. US, GB, DE)" },
        ] satisfies { value: "all" | "selected"; label: string; desc: string }[]
      ).map((opt) => (
        <label
          key={opt.value}
          style={{
            display: "flex",
            alignItems: "flex-start",
            gap: "12px",
            padding: "12px 14px",
            border: `1.5px solid ${countries === opt.value ? "#2c6ecb" : "#e3e3e3"}`,
            borderRadius: "8px",
            background: countries === opt.value ? "#f0f5ff" : "#fff",
            cursor: "pointer",
            transition: "all 0.12s ease",
          }}
        >
          <input
            type="radio"
            name="countries"
            value={opt.value}
            checked={countries === opt.value}
            onChange={() => setCountries(opt.value)}
            style={{ marginTop: "2px", accentColor: "#2c6ecb", flexShrink: 0 }}
          />
          <div>
            <p style={{ margin: "0 0 2px", fontSize: "14px", fontWeight: 600, color: "#202223" }}>{opt.label}</p>
            <p style={{ margin: 0, fontSize: "12px", color: "#6d7175" }}>{opt.desc}</p>
          </div>
        </label>
      ))}
    </div>
    {countries === "selected" && (
      <div style={{ marginTop: "14px" }}>
        <label style={labelStyle} htmlFor="country-codes">Country codes</label>
        <input
          id="country-codes"
          value={selectedCountries}
          onChange={(e) => setSelectedCountries((e.target as HTMLInputElement).value)}
          placeholder="e.g. US, GB, DE, FR, CA"
