              fontSize: "13px",
              fontWeight: 600,
              color: "#6d7175",
              textTransform: "uppercase",
              letterSpacing: "0.5px",
              margin: "0 0 10px",
            }}
          >
            Start from scratch
          </p>
          <div
            style={{
              display: "inline-block",
              border: `2px dashed ${hoveredCard === "__blank" ? "#005bd3" : "#c9cccf"}`,
              borderRadius: "10px",
              padding: "16px 24px",
              background: hoveredCard === "__blank" ? "#f3f7ff" : "#f9fafb",
              transition: "all 0.15s ease",
