  bottoms: "Bottoms",
  dresses: "Dresses",
  shoes: "Shoes",
  kids: "Kids",
  rings: "Rings",
  sportswear: "Sportswear",
  general: "General",
};

const CATEGORY_ICONS: Record<string, string> = {
