  bottoms: "👖",
  dresses: "👗",
  shoes: "👟",
  kids: "🧒",
  rings: "💍",
  sportswear: "🏃",
  general: "📏",
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  return new Date(date).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// Style constants — mirrors dashboard design language
// ---------------------------------------------------------------------------

const cardStyle: React.CSSProperties = {
  background: "#ffffff",
  border: "1px solid #e3e3e3",
  borderRadius: "12px",
  padding: "20px",
};

const sectionTitle: React.CSSProperties = {
  fontSize: "15px",
  fontWeight: 650,
  color: "#202223",
  margin: 0,
};

const badgeStyle = (tone: "success" | "neutral" | "info"): React.CSSProperties => ({
  display: "inline-block",
  padding: "2px 8px",
  borderRadius: "10px",
  fontSize: "11px",
  fontWeight: 600,
  lineHeight: "18px",
  background: tone === "success" ? "#c8f9e8" : tone === "info" ? "#e4e5f7" : "#e4e5e7",
  color: tone === "success" ? "#0d6832" : tone === "info" ? "#3b3f8c" : "#6d7175",
});

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

interface TemplateSectionProps {
  templates: Array<{ name: string; category: string; gender: string; rowCount: number }>;
  categories: string[];
  isLoading: boolean;
  onClose: () => void;
  fetcher: ReturnType<typeof useFetcher<typeof action>>;
}

