        <s-section>
          <div
            style={{
              ...cardStyle,
              background: "#fff8ec",
              border: "1px solid #ffd79d",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: "16px",
            }}
          >
            <div style={{ display: "flex", alignItems: "flex-start", gap: "12px" }}>
              <span style={{ fontSize: "20px", flexShrink: 0, marginTop: "1px" }}>
                ⚠️
              </span>
              <div>
                <p
                  style={{
                    margin: "0 0 4px",
                    fontSize: "14px",
                    fontWeight: 600,
                    color: "#202223",
                  }}
                >
                  Chart limit reached
                </p>
                <p style={{ margin: 0, fontSize: "13px", color: "#6d7175" }}>
                  You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
                  {plan.name} plan. Upgrade to Starter for unlimited charts with no
                  hidden fees.
                </p>
              </div>
            </div>
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* TEMPLATE PICKER                                                   */}
      {/* ================================================================ */}
      {showTemplates && (
        <TemplatePicker
          templates={templates}
          categories={categories}
          isLoading={isLoading}
          onClose={() => setShowTemplates(false)}
          fetcher={fetcher}
        />
      )}

      {/* ================================================================ */}
      {/* SEARCH + FILTER BAR (only when charts exist)                     */}
      {/* ================================================================ */}
      {charts.length > 0 && (
        <s-section>
          <div style={cardStyle}>
            {/* Search input */}
            <div style={{ marginBottom: "12px" }}>
              <div
                style={{
                  position: "relative",
                  display: "flex",
                  alignItems: "center",
                }}
              >
                <span
                  style={{
                    position: "absolute",
                    left: "12px",
                    fontSize: "14px",
                    color: "#8c9196",
                    pointerEvents: "none",
                  }}
                >
                  🔍
                </span>
                <input
                  type="text"
                  placeholder="Search charts..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery((e.target as HTMLInputElement).value)}
                  style={{
                    width: "100%",
                    border: "1px solid #c9cccf",
                    borderRadius: "8px",
                    padding: "8px 12px 8px 36px",
                    fontSize: "14px",
