  const d = typeof date === "string" ? new Date(date) : date;
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

  const [
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    subscription,
    recentCharts,
    widgetConfig,
    recommenderConfig,
    assignmentCount,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.sizeChart.count({ where: { shop, status: "active" } }),
    db.sizeChart.count({ where: { shop, status: "draft" } }),
    db.analyticsEvent.count({
      where: { shop, eventType: "view", createdAt: { gte: thirtyDaysAgo } },
    }),
    db.analyticsEvent.count({ where: { shop, eventType: "recommend" } }),
    db.subscription.findUnique({ where: { shop } }),
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      take: 5,
      select: {
        id: true,
        name: true,
        category: true,
        status: true,
        updatedAt: true,
        _count: { select: { assignments: true } },
      },
    }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.chartAssignment.count({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  const hasChart = chartCount > 0;
  const hasAssignment = assignmentCount > 0;
  const hasWidget = widgetConfig !== null;
  const hasRecommender =
    recommenderConfig !== null && recommenderConfig.enabled;

  const setupSteps = [
    {
      key: "create-chart",
      title: "Create your first size chart",
      description:
        "Choose from 9 ready-made templates or build a custom chart from scratch.",
      done: hasChart,
      actionLabel: "Create chart",
      actionUrl: "/app/size-charts",
    },
    {
      key: "customize-widget",
      title: "Style your size chart widget",
      description:
        "Customize colors, layout, and text to match your store's brand.",
      done: hasWidget,
      actionLabel: "Go to Appearance",
      actionUrl: "/app/widget",
    },
    {
      key: "assign-products",
      title: "Assign chart to products",
      description:
        "Link your chart to products, collections, or tags so it shows automatically.",
      done: hasAssignment,
      actionLabel: "Assign products",
      actionUrl: "/app/size-charts",
    },
  ];

  const completedCount = setupSteps.filter((s) => s.done).length;

  return {
    shop,
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts: recentCharts.map((c) => ({
      ...c,
      assignmentCount: c._count.assignments,
      updatedAt: c.updatedAt.toISOString(),
    })),
    hasRecommender,
    setupSteps,
    completedCount,
    totalSteps: setupSteps.length,
  };
};

// ---------------------------------------------------------------------------
// Progress bar sub-component (no Polaris equivalent for custom fill colors)
// ---------------------------------------------------------------------------

interface ProgressBarProps {
  value: number; // 0–100
  danger?: boolean;
}

function ProgressBar({ value, danger = false }: ProgressBarProps) {
  return (
    <div
      style={{
        height: "6px",
        background: "#e4e5e7",
        borderRadius: "3px",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          height: "100%",
          background: danger ? "#d72c0d" : "#1a73e8",
          borderRadius: "3px",
          width: `${Math.min(100, value)}%`,
          transition: "width 0.3s ease",
        }}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step circle sub-component (custom visual — no Polaris equivalent)
// ---------------------------------------------------------------------------

function StepCircle({ done }: { done: boolean }) {
  return (
    <div
      style={{
        width: "22px",
        height: "22px",
        borderRadius: "50%",
        border: done ? "none" : "2px solid #c9cccf",
        background: done ? "#1a73e8" : "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        marginTop: "1px",
        color: "#fff",
        fontSize: "12px",
        fontWeight: 700,
      }}
    >
      {done && "✓"}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function Dashboard() {
  const {
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts,
    setupSteps,
    completedCount,
    totalSteps,
  } = useLoaderData<typeof loader>();

  const [setupOpen, setSetupOpen] = useState(true);
  const [expandedStep, setExpandedStep] = useState<string | null>(
    setupSteps.find((s) => !s.done)?.key ?? null,
  );

  const isSetupComplete = completedCount === totalSteps;
  const isFreePlan = plan.id === "free";
  const maxCharts = plan.limits.maxCharts;
  const setupProgressPct = Math.round((completedCount / totalSteps) * 100);
  const chartUsagePct =
    maxCharts > 0 ? Math.round((chartCount / maxCharts) * 100) : 0;

  return (
    <s-page heading="Dashboard">
      {/* Primary action */}
      <s-button slot="primary-action" variant="primary" href="/app/size-charts">
        Create Size Chart
      </s-button>

      {/* ================================================================ */}
      {/* SETUP GUIDE — collapsible, prominent                              */}
      {/* ================================================================ */}
      {!isSetupComplete && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              {/* Header row */}
              <s-stack direction="inline" gap="base">
                <s-stack direction="block" gap="small-200">
                  <s-heading>Setup guide</s-heading>
                  <s-text tone="neutral">
                    Use this personalized guide to get you started with Size
                    Chart &amp; Recommender.
                  </s-text>
                </s-stack>
                <s-button onClick={() => setSetupOpen(!setupOpen)}>
                  {setupOpen ? "Hide" : "Show"}
                </s-button>
              </s-stack>

              {/* Progress */}
              <s-stack direction="block" gap="small-200">
                <s-text tone="neutral">
                  {completedCount} of {totalSteps} steps completed
                </s-text>
                <ProgressBar value={setupProgressPct} />
              </s-stack>

              {/* Steps */}
              {setupOpen && (
                <s-stack direction="block" gap="small-200">
                  {setupSteps.map((step) => (
                    <s-box
                      key={step.key}
                      padding="base"
                      borderWidth="base"
                      borderRadius="base"
                    >
                      <s-stack
                        direction="inline"
                        gap="base"
                        onClick={() =>
                          setExpandedStep(
                            expandedStep === step.key ? null : step.key,
                          )
                        }
                        style={{ cursor: "pointer" }}
                      >
                        <StepCircle done={step.done} />
                        <s-stack direction="block" gap="small-200">
                          <s-text
                            tone={step.done ? "subdued" : undefined}
                            style={{
                              textDecoration: step.done
                                ? "line-through"
                                : "none",
                            }}
                          >
                            {step.title}
                          </s-text>

                          {expandedStep === step.key && !step.done && (
                            <s-stack direction="block" gap="base">
                              <s-text tone="neutral">
                                {step.description}
                              </s-text>
                              <s-button
                                variant="primary"
                                href={step.actionUrl}
                              >
                                {step.actionLabel}
                              </s-button>
                            </s-stack>
                          )}
                        </s-stack>
                      </s-stack>
                    </s-box>
                  ))}
                </s-stack>
              )}
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* STATS OVERVIEW                                                    */}
      {/* ================================================================ */}
      <s-section>
        <s-stack direction="inline" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{chartCount}</s-heading>
              <s-text tone="neutral">Total charts</s-text>
              <s-text tone="subdued">
                {activeChartCount} active · {draftChartCount} draft
              </s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{activeChartCount}</s-heading>
              <s-text tone="neutral">Published charts</s-text>
              <s-text tone="subdued">Visible on storefront</s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{monthlyViews}x</s-heading>
              <s-text tone="neutral">Views — current month</s-text>
              <s-text tone="subdued">Last 30 days</s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{totalRecommendations}</s-heading>
              <s-text tone="neutral">AI recommendations</s-text>
              <s-text tone="subdued">
                {plan.limits.aiRecommender ? "Active" : "Upgrade to unlock"}
              </s-text>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* CTA BANNER — show size charts for all products                    */}
      {/* ================================================================ */}
      {chartCount === 0 && (
        <s-section>
          <s-banner
            tone="info"
            heading="Show size charts for all your products"
          >
            <s-stack direction="block" gap="base">
              <s-text tone="neutral">
                Help your customers easily find the right size for every
                product. Reduce returns by up to 40%.
              </s-text>
              <s-stack direction="inline" gap="base">
                <s-button variant="primary" href="/app/size-charts">
                  Create chart
                </s-button>
                <s-button href="/app/pricing">View plans</s-button>
              </s-stack>
            </s-stack>
          </s-banner>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* RECENT SIZE CHARTS                                                */}
      {/* ================================================================ */}
      <s-section>
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="block" gap="base">
            {/* Section header */}
            <s-stack direction="inline" gap="base">
              <s-heading>
                {chartCount > 0
                  ? "Recent size charts"
                  : "Create your size chart!"}
              </s-heading>
              {chartCount > 0 && (
                <s-link href="/app/size-charts">View all</s-link>
              )}
            </s-stack>

            {recentCharts.length === 0 ? (
              /* Empty state */
              <s-stack direction="block" gap="base">
                <s-text tone="neutral">
                  Create various types of size charts, AI Size Recommendations.
                </s-text>
                <s-button variant="primary" href="/app/size-charts">
                  Create a Size Chart
                </s-button>
              </s-stack>
            ) : (
              /* Chart rows */
              <s-stack direction="block" gap="small-200">
                {recentCharts.map((chart) => (
                  <s-box
                    key={chart.id}
                    padding="base"
                    borderWidth="base"
                    borderRadius="base"
                  >
                    <s-stack direction="inline" gap="base">
                      <s-stack direction="block" gap="small-200">
                        <s-link href={`/app/size-charts/${chart.id}`}>
                          {chart.name}
