interface ProgressBarProps {
  value: number; // 0–100
  danger?: boolean;
}

function ProgressBar({ value, danger = false }: ProgressBarProps) {
  return (
    <div
      style={{
        height: "6px",
        background: "#e4e5e7",
        borderRadius: "3px",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          height: "100%",
          background: danger ? "#d72c0d" : "#1a73e8",
          borderRadius: "3px",
          width: `${Math.min(100, value)}%`,
          transition: "width 0.3s ease",
        }}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step circle sub-component (custom visual — no Polaris equivalent)
// ---------------------------------------------------------------------------

function StepCircle({ done }: { done: boolean }) {
  return (
    <div
      style={{
        width: "22px",
        height: "22px",
        borderRadius: "50%",
        border: done ? "none" : "2px solid #c9cccf",
        background: done ? "#1a73e8" : "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        marginTop: "1px",
        color: "#fff",
        fontSize: "12px",
        fontWeight: 700,
      }}
    >
      {done && "✓"}
    </div>
  );
}

