// ---------------------------------------------------------------------------
// Shared input styles
// ---------------------------------------------------------------------------

const INPUT_STYLE: React.CSSProperties = {
  padding: "8px 12px",
  border: "1px solid #8c9196",
  borderRadius: "8px",
  fontSize: "14px",
  width: "100%",
  outline: "none",
  boxSizing: "border-box",
  fontFamily: "inherit",
  color: "#202223",
  backgroundColor: "#fff",
  transition: "border-color 0.2s",
};

const LABEL_STYLE: React.CSSProperties = {
  fontWeight: 600,
  fontSize: "13px",
  color: "#202223",
  marginBottom: "4px",
  display: "block",
};

const FIELD_STYLE: React.CSSProperties = {
  display: "flex",
  flexDirection: "column",
  gap: "4px",
  width: "100%",
};

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

function FieldLabel({ children }: { children: React.ReactNode }) {
  return <span style={LABEL_STYLE}>{children}</span>;
}

function TextInput({
  value,
  onChange,
  placeholder,
}: {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
}) {
  return (
    <input
      type="text"
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      style={INPUT_STYLE}
      onFocus={(e) => {
        (e.currentTarget as HTMLInputElement).style.borderColor = "#005bd3";
      }}
      onBlur={(e) => {
        (e.currentTarget as HTMLInputElement).style.borderColor = "#8c9196";
      }}
    />
  );
}

function ColorPickerField({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <s-box padding="base" borderWidth="base" borderRadius="base">
      <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
        <FieldLabel>{label}</FieldLabel>
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <div
            style={{
              width: "32px",
              height: "32px",
              borderRadius: "6px",
              backgroundColor: value,
              border: "1px solid #c9cccf",
              position: "relative",
              overflow: "hidden",
              flexShrink: 0,
              cursor: "pointer",
            }}
          >
            <input
              type="color"
              value={value}
              onChange={(e) => onChange(e.target.value)}
              style={{
                position: "absolute",
                inset: 0,
                opacity: 0,
                width: "100%",
                height: "100%",
                cursor: "pointer",
                padding: 0,
                border: "none",
              }}
            />
          </div>
          <input
            type="text"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            maxLength={7}
            style={{
              ...INPUT_STYLE,
              width: "90px",
              fontFamily: "monospace",
              fontSize: "13px",
            }}
          />
        </div>
      </div>
    </s-box>
  );
