import { useEffect } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [config, subscription] = await Promise.all([
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  return {
    config: config ?? { enabled: false, algorithm: "basic", bodyTypes: "[]", sizingRules: "{}" },
    plan,
    canUseAi: hasFeature(plan.id, "aiRecommender"),
    canUseAdvanced: hasFeature(plan.id, "advancedAi"),
  };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "toggle": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
          return { error: "AI recommender requires Growth plan or higher" };
        }
        const current = await db.recommenderConfig.findUnique({ where: { shop } });
        await db.recommenderConfig.upsert({
          where: { shop },
          update: { enabled: !current?.enabled },
          create: { shop, enabled: true },
        });
        return { ok: true, message: current?.enabled ? "AI Recommender disabled" : "AI Recommender enabled" };
      }
      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
  }
};

export default function Recommender() {
  const { config, plan, canUseAi, canUseAdvanced } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data) shopify.toast.show(fetcher.data.message ?? "Success");
    else if (fetcher.data && "error" in fetcher.data) shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
  }, [fetcher.data, shopify]);

  const isLoading = fetcher.state !== "idle";

  return (
    <s-page heading="AI Size Recommender">
      {!canUseAi && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base" background="subdued">
            <s-stack direction="block" gap="base">
              <s-heading>Unlock AI Size Recommendations</s-heading>
              <s-paragraph>
                Help customers find their perfect size with AI-powered recommendations
                based on height, weight, and body type. Available on Growth plan and above.
              </s-paragraph>
              <s-button href="/app/pricing" variant="primary">Upgrade to Growth — $9.99/mo</s-button>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {canUseAi && (
        <s-section heading="Recommender Status">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-text>Status: {config.enabled ? "Active" : "Disabled"}</s-text>
              <s-text tone="neutral">
                {config.enabled
                  ? "Customers can get AI-powered size recommendations on your storefront"
                  : "Enable to show the 'Find My Size' button on product pages"}
              </s-text>
              <fetcher.Form method="post">
                <input type="hidden" name="intent" value="toggle" />
                <s-button type="submit" variant={config.enabled ? "tertiary" : "primary"} loading={isLoading}>
                  {config.enabled ? "Disable Recommender" : "Enable Recommender"}
                </s-button>
              </fetcher.Form>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {canUseAi && (
        <s-section heading="How It Works">
          <s-stack direction="inline" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>1. Customer enters info</s-text>
              <s-text tone="neutral">Height, weight, body type, and gender</s-text>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>2. AI analyzes</s-text>
              <s-text tone="neutral">Estimates body measurements and matches to your size chart</s-text>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>3. Recommendation</s-text>
              <s-text tone="neutral">Shows best size with confidence score and alternatives</s-text>
            </s-box>
          </s-stack>
        </s-section>
      )}

      {canUseAi && config.enabled && (
        <s-section heading="Algorithm">
          <s-stack direction="block" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>Basic Algorithm</s-text>
              <s-text tone="neutral">
                Statistical body proportion model. Fast, accurate, no API costs.
              </s-text>
              <s-text tone="success">{config.algorithm === "basic" ? "Currently active" : "Available"}</s-text>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>Advanced ML Algorithm</s-text>
              <s-text tone="neutral">
                Improves over time using your store's return data.
              </s-text>
              {canUseAdvanced
                ? <s-text tone="success">{config.algorithm === "advanced" ? "Currently active" : "Available"}</s-text>
                : <s-text tone="caution">Requires Pro plan — $19.99/mo</s-text>
              }
            </s-box>
          </s-stack>
        </s-section>
      )}

      {canUseAi && config.enabled && (
        <s-section heading="Supported Body Types">
          <s-paragraph>These body types are shown to customers in the recommendation form.</s-paragraph>
          <s-stack direction="inline" gap="base">
            {[
              { name: "Slim", desc: "Narrower proportions, fitted preferences" },
              { name: "Regular", desc: "Standard proportions, true-to-size" },
              { name: "Athletic", desc: "Broader chest/shoulders, narrower waist" },
              { name: "Plus", desc: "Fuller proportions, relaxed fit preferences" },
            ].map((type) => (
              <s-box key={type.name} padding="base" borderWidth="base" borderRadius="base">
                <s-text>{type.name}</s-text>
                <s-text tone="neutral">{type.desc}</s-text>
              </s-box>
            ))}
          </s-stack>
        </s-section>
      )}

      <s-section slot="aside" heading="Current Plan">
        <s-stack direction="block" gap="small-200">
          <s-text>{plan.name}</s-text>
          <s-text tone="neutral">{canUseAi ? "AI features included" : "AI features not included"}</s-text>
          {!canUseAdvanced && canUseAi && (
            <s-button href="/app/pricing">Upgrade for Advanced AI</s-button>
          )}
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="Performance">
        <s-unordered-list>
          <s-list-item>Basic: ~5ms response time, $0/use</s-list-item>
          <s-list-item>Advanced: ~50ms, $0/use</s-list-item>
          <s-list-item>All computation server-side</s-list-item>
        </s-unordered-list>
      </s-section>
    </s-page>
  );
}

import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan } from "../lib/plans";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  const d = typeof date === "string" ? new Date(date) : date;
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

  const [
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    subscription,
    recentCharts,
    widgetConfig,
    recommenderConfig,
    assignmentCount,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.sizeChart.count({ where: { shop, status: "active" } }),
    db.sizeChart.count({ where: { shop, status: "draft" } }),
    db.analyticsEvent.count({
      where: { shop, eventType: "view", createdAt: { gte: thirtyDaysAgo } },
    }),
    db.analyticsEvent.count({ where: { shop, eventType: "recommend" } }),
    db.subscription.findUnique({ where: { shop } }),
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      take: 5,
      select: {
        id: true,
        name: true,
        category: true,
        status: true,
        updatedAt: true,
        _count: { select: { assignments: true } },
      },
    }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.chartAssignment.count({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  const hasChart = chartCount > 0;
  const hasAssignment = assignmentCount > 0;
  const hasWidget = widgetConfig !== null;
  const hasRecommender =
    recommenderConfig !== null && recommenderConfig.enabled;

  const setupSteps = [
    {
      key: "create-chart",
      title: "Create your first size chart",
      description:
        "Choose from 9 ready-made templates or build a custom chart from scratch.",
      done: hasChart,
      actionLabel: "Create chart",
      actionUrl: "/app/size-charts",
    },
    {
      key: "customize-widget",
      title: "Style your size chart widget",
      description:
        "Customize colors, layout, and text to match your store's brand.",
      done: hasWidget,
      actionLabel: "Go to Appearance",
      actionUrl: "/app/widget",
    },
    {
      key: "assign-products",
      title: "Assign chart to products",
      description:
        "Link your chart to products, collections, or tags so it shows automatically.",
      done: hasAssignment,
      actionLabel: "Assign products",
      actionUrl: "/app/size-charts",
    },
  ];

  const completedCount = setupSteps.filter((s) => s.done).length;

  return {
    shop,
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts: recentCharts.map((c) => ({
      ...c,
      assignmentCount: c._count.assignments,
      updatedAt: c.updatedAt.toISOString(),
    })),
    hasRecommender,
    setupSteps,
    completedCount,
    totalSteps: setupSteps.length,
  };
};

// ---------------------------------------------------------------------------
// Progress bar sub-component (no Polaris equivalent for custom fill colors)
// ---------------------------------------------------------------------------

interface ProgressBarProps {
  value: number; // 0–100
  danger?: boolean;
}

function ProgressBar({ value, danger = false }: ProgressBarProps) {
  return (
    <div
      style={{
        height: "6px",
        background: "#e4e5e7",
        borderRadius: "3px",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          height: "100%",
          background: danger ? "#d72c0d" : "#1a73e8",
          borderRadius: "3px",
          width: `${Math.min(100, value)}%`,
          transition: "width 0.3s ease",
        }}
      />
    </div>
  );
}

// ---------------------------------------------------------------------------
// Step circle sub-component (custom visual — no Polaris equivalent)
// ---------------------------------------------------------------------------

function StepCircle({ done }: { done: boolean }) {
  return (
    <div
      style={{
        width: "22px",
        height: "22px",
        borderRadius: "50%",
        border: done ? "none" : "2px solid #c9cccf",
        background: done ? "#1a73e8" : "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        marginTop: "1px",
        color: "#fff",
        fontSize: "12px",
        fontWeight: 700,
      }}
    >
      {done && "✓"}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function Dashboard() {
  const {
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts,
    setupSteps,
    completedCount,
    totalSteps,
  } = useLoaderData<typeof loader>();

  const [setupOpen, setSetupOpen] = useState(true);
  const [expandedStep, setExpandedStep] = useState<string | null>(
    setupSteps.find((s) => !s.done)?.key ?? null,
  );

  const isSetupComplete = completedCount === totalSteps;
  const isFreePlan = plan.id === "free";
  const maxCharts = plan.limits.maxCharts;
  const setupProgressPct = Math.round((completedCount / totalSteps) * 100);
  const chartUsagePct =
    maxCharts > 0 ? Math.round((chartCount / maxCharts) * 100) : 0;

  return (
    <s-page heading="Dashboard">
      {/* Primary action */}
      <s-button slot="primary-action" variant="primary" href="/app/size-charts">
        Create Size Chart
      </s-button>

      {/* ================================================================ */}
      {/* SETUP GUIDE — collapsible, prominent                              */}
      {/* ================================================================ */}
      {!isSetupComplete && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              {/* Header row */}
              <s-stack direction="inline" gap="base">
                <s-stack direction="block" gap="small-200">
                  <s-heading>Setup guide</s-heading>
                  <s-text tone="neutral">
                    Use this personalized guide to get you started with Size
                    Chart &amp; Recommender.
                  </s-text>
                </s-stack>
                <s-button onClick={() => setSetupOpen(!setupOpen)}>
                  {setupOpen ? "Hide" : "Show"}
                </s-button>
              </s-stack>

              {/* Progress */}
              <s-stack direction="block" gap="small-200">
                <s-text tone="neutral">
                  {completedCount} of {totalSteps} steps completed
                </s-text>
                <ProgressBar value={setupProgressPct} />
              </s-stack>

              {/* Steps */}
              {setupOpen && (
                <s-stack direction="block" gap="small-200">
                  {setupSteps.map((step) => (
                    <s-box
                      key={step.key}
                      padding="base"
                      borderWidth="base"
                      borderRadius="base"
                    >
                      <s-clickable
                        onClick={() =>
                          setExpandedStep(
                            expandedStep === step.key ? null : step.key,
                          )
                        }
                      >
                        <s-stack direction="inline" gap="base">
                          <StepCircle done={step.done} />
                          <s-stack direction="block" gap="small-200">
                            <s-text tone={step.done ? "neutral" : undefined}>
                              {step.done ? <s>{step.title}</s> : step.title}
                            </s-text>

                            {expandedStep === step.key && !step.done && (
                              <s-stack direction="block" gap="base">
                                <s-text tone="neutral">
                                  {step.description}
                                </s-text>
                                <s-button
                                  variant="primary"
                                  href={step.actionUrl}
                                >
                                  {step.actionLabel}
                                </s-button>
                              </s-stack>
                            )}
                          </s-stack>
                        </s-stack>
                      </s-clickable>
                    </s-box>
                  ))}
                </s-stack>
              )}
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* STATS OVERVIEW                                                    */}
      {/* ================================================================ */}
      <s-section>
        <s-stack direction="inline" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{chartCount}</s-heading>
              <s-text tone="neutral">Total charts</s-text>
              <s-text tone="neutral">
                {activeChartCount} active · {draftChartCount} draft
              </s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{activeChartCount}</s-heading>
              <s-text tone="neutral">Published charts</s-text>
              <s-text tone="neutral">Visible on storefront</s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{monthlyViews}x</s-heading>
              <s-text tone="neutral">Views — current month</s-text>
              <s-text tone="neutral">Last 30 days</s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{totalRecommendations}</s-heading>
              <s-text tone="neutral">AI recommendations</s-text>
              <s-text tone="neutral">
                {plan.limits.aiRecommender ? "Active" : "Upgrade to unlock"}
              </s-text>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* CTA BANNER — show size charts for all products                    */}
      {/* ================================================================ */}
      {chartCount === 0 && (
        <s-section>
          <s-banner
            tone="info"
            heading="Show size charts for all your products"
          >
            <s-stack direction="block" gap="base">
              <s-text tone="neutral">
                Help your customers easily find the right size for every
                product. Reduce returns by up to 40%.
              </s-text>
              <s-stack direction="inline" gap="base">
                <s-button variant="primary" href="/app/size-charts">
                  Create chart
                </s-button>
                <s-button href="/app/pricing">View plans</s-button>
              </s-stack>
            </s-stack>
          </s-banner>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* RECENT SIZE CHARTS                                                */}
      {/* ================================================================ */}
      <s-section>
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="block" gap="base">
            {/* Section header */}
            <s-stack direction="inline" gap="base">
              <s-heading>
                {chartCount > 0
                  ? "Recent size charts"
                  : "Create your size chart!"}
              </s-heading>
              {chartCount > 0 && (
                <s-link href="/app/size-charts">View all</s-link>
              )}
            </s-stack>

            {recentCharts.length === 0 ? (
              /* Empty state */
              <s-stack direction="block" gap="base">
                <s-text tone="neutral">
                  Create various types of size charts, AI Size Recommendations.
                </s-text>
                <s-button variant="primary" href="/app/size-charts">
                  Create a Size Chart
                </s-button>
              </s-stack>
            ) : (
              /* Chart rows */
              <s-stack direction="block" gap="small-200">
                {recentCharts.map((chart) => (
                  <s-box
                    key={chart.id}
                    padding="base"
                    borderWidth="base"
                    borderRadius="base"
                  >
                    <s-stack direction="inline" gap="base">
                      <s-stack direction="block" gap="small-200">
                        <s-link href={`/app/size-charts/${chart.id}`}>
                          {chart.name}
                        </s-link>
                        <s-stack direction="inline" gap="small-200">
                          <s-badge tone="info">{chart.category}</s-badge>
                          <s-badge
                            tone={
                              chart.status === "active" ? "success" : "neutral"
                            }
                          >
                            {chart.status === "active" ? "Active" : "Draft"}
                          </s-badge>
                          <s-text tone="neutral">
                            {chart.assignmentCount > 0
                              ? `${chart.assignmentCount} product${chart.assignmentCount > 1 ? "s" : ""}`
                              : "No assignments"}
                          </s-text>
                        </s-stack>
                      </s-stack>
                      <s-text tone="neutral">
                        {formatDate(chart.updatedAt)}
                      </s-text>
                    </s-stack>
                  </s-box>
                ))}
              </s-stack>
            )}
          </s-stack>
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* ENABLE APP — app status                                           */}
      {/* ================================================================ */}
      <s-section>
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="block" gap="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>Enable app</s-heading>
              <s-text tone="neutral">
                Keep the app active to display size charts on your store.
              </s-text>
            </s-stack>

            <s-box padding="base" borderWidth="base" borderRadius="base" background="subdued">
              <s-stack direction="inline" gap="base">
                <s-stack direction="inline" gap="small-200">
                  <s-text>Theme App Extension</s-text>
                  <s-badge tone="info">Required</s-badge>
                </s-stack>
                <s-badge tone={activeChartCount > 0 ? "success" : "neutral"}>
                  {activeChartCount > 0 ? "Active" : "Inactive"}
                </s-badge>
              </s-stack>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base" background="subdued">
              <s-stack direction="inline" gap="base">
                <s-stack direction="inline" gap="small-200">
                  <s-text>App Block</s-text>
                  <s-badge tone="neutral">Optional</s-badge>
                </s-stack>
                <s-badge tone={activeChartCount > 0 ? "success" : "neutral"}>
                  {activeChartCount > 0 ? "Active" : "Inactive"}
                </s-badge>
              </s-stack>
            </s-box>
          </s-stack>
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Plan & Usage                                              */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Your plan">
        <s-stack direction="block" gap="base">
          <s-stack direction="inline" gap="small-200">
            <s-badge tone={isFreePlan ? "neutral" : "success"}>
              {plan.name}
            </s-badge>
            <s-text tone="neutral">
              {plan.price === 0 ? "Free" : `$${plan.price}/mo`}
            </s-text>
          </s-stack>

          {isFreePlan && maxCharts > 0 && (
            <s-stack direction="block" gap="small-200">
              <s-text tone="neutral">
                {chartCount} / {maxCharts} charts used
              </s-text>
              <ProgressBar
                value={chartUsagePct}
                danger={chartCount >= maxCharts}
              />
            </s-stack>
          )}

          <s-unordered-list>
            {plan.features.slice(0, 4).map((f, i) => (
              <s-list-item key={i}>{f}</s-list-item>
            ))}
          </s-unordered-list>

          {isFreePlan && (
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick links                                               */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick links">
        <s-unordered-list>
          <s-list-item>
            <s-link href="/app/size-charts">Size Charts</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/widget">Widget Appearance</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/recommender">AI Recommender</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/analytics">Analytics</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/settings">Settings</s-link>
          </s-list-item>
        </s-unordered-list>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Help & Resources                                          */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Need help?">
        <s-stack direction="block" gap="base">
          <s-text tone="neutral">We respond within 2 hours.</s-text>
          <s-unordered-list>
            <s-list-item>
              <s-link href="mailto:support@sizechart.app">Email support</s-link>
            </s-list-item>
            <s-list-item>
              <s-link href="/app/settings">App settings</s-link>
            </s-list-item>
          </s-unordered-list>
          {plan.limits.prioritySupport && (
            <s-badge tone="success">Priority support</s-badge>
          )}
        </s-stack>
      </s-section>
    </s-page>
  );
}

