265→            >
266→              <s-stack direction="block" gap="small-200">
267→                <s-text>{t.label}</s-text>
268→                <s-text tone="neutral">{t.desc}</s-text>
269→              </s-stack>
270→            </s-box>
271→          </s-clickable>
272→        );
273→      })}
274→    </s-stack>
275→  );
276→}
277→
278→// ---------------------------------------------------------------------------
279→// Live Preview — intentional custom styling kept as-is
280→// ---------------------------------------------------------------------------
281→
282→function WidgetPreview({ config }: { config: LocalConfig }) {
283→  const radius = `${config.borderRadius}px`;
284→
285→  return (
286→    <div
287→      style={{
288→        backgroundColor: config.backgroundColor,
289→        borderRadius: radius,
290→        border: `1px solid ${config.primaryColor}33`,
291→        padding: "20px",
292→        fontFamily: "system-ui, sans-serif",
293→        boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
294→        maxWidth: "320px",
295→        width: "100%",
296→      }}
297→    >
298→      {/* Header */}
299→      <div
300→        style={{
301→          borderBottom: `1px solid ${config.primaryColor}22`,
302→          paddingBottom: "12px",
303→          marginBottom: "16px",
304→          display: "flex",
305→          alignItems: "center",
306→          justifyContent: "space-between",
307→        }}
308→      >
309→        <span
310→          style={{
311→            fontSize: "16px",
