337→        }}
338→      >
339→        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "12px" }}>
340→          <thead>
341→            <tr style={{ backgroundColor: `${config.primaryColor}15` }}>
342→              {["Size", "S", "M", "L", "XL"].map((h) => (
343→                <th
344→                  key={h}
345→                  style={{
