352→                >
353→                  {h}
354→                </th>
355→              ))}
356→            </tr>
357→          </thead>
358→          <tbody>
359→            {[
360→              { label: "Bust", values: ["32", "34", "36", "38"] },
361→              { label: "Waist", values: ["26", "28", "30", "32"] },
