 439→                    }}
 440→                  >
 441→                    {CATEGORY_LABELS[cat] ?? cat}
 442→                  </p>
 443→                  <div
 444→                    style={{
 445→                      display: "grid",
 446→                      gridTemplateColumns: "repeat(auto-fill, minmax(150px, 1fr))",
 447→                      gap: "12px",
 448→                    }}
 449→                  >
 450→                    {group.map((template) => {
 451→                      const cardKey = template.name;
 452→                      const isHovered = hoveredCard === cardKey;
 453→                      return (
 454→                        <div
 455→                          key={template.name}
 456→                          style={{
 457→                            background: isHovered ? "#f3f7ff" : "#fff",
 458→                            border: `1px solid ${isHovered ? "#005bd3" : "#e3e3e3"}`,
 459→                            borderRadius: "10px",
 460→                            padding: "14px",
 461→                            cursor: "pointer",
 462→                            transition: "all 0.15s ease",
 463→                            display: "flex",
 464→                            flexDirection: "column",
 465→                            alignItems: "center",
 466→                            textAlign: "center",
 467→                          }}
 468→                          onMouseEnter={() => setHoveredCard(cardKey)}
 469→                          onMouseLeave={() => setHoveredCard(null)}
 470→                        >
 471→                          <div
 472→                            style={{
 473→                              width: "40px",
 474→                              height: "40px",
 475→                              borderRadius: "50%",
 476→                              background: "#f0f5ff",
 477→                              display: "flex",
 478→                              alignItems: "center",
 479→                              justifyContent: "center",
 480→                              fontSize: "20px",
 481→                              marginBottom: "8px",
 482→                            }}
 483→                          >
 484→                            {CATEGORY_ICONS[template.category] ?? "📏"}
 485→                          </div>
 486→                          <p
 487→                            style={{
 488→                              margin: "0 0 2px",
 489→                              fontWeight: 600,
 490→                              fontSize: "13px",
 491→                              color: "#202223",
 492→                              lineHeight: "1.3",
 493→                            }}
 494→                          >
 495→                            {template.name}
 496→                          </p>
 497→                          <p
 498→                            style={{
 499→                              margin: "0 0 10px",
 500→                              fontSize: "11px",
 501→                              color: "#6d7175",
 502→                            }}
 503→                          >
 504→                            {template.rowCount} sizes
 505→                          </p>
 506→                          <fetcher.Form method="post">
 507→                            <input type="hidden" name="intent" value="create-from-template" />
 508→                            <input type="hidden" name="templateName" value={template.name} />
 509→                            <s-button variant="primary" type="submit" loading={isLoading}>
 510→                              Use template
 511→                            </s-button>
 512→                          </fetcher.Form>
 513→                        </div>
 514→                      );
 515→                    })}
 516→                  </div>
 517→                </div>
 518→              );
 519→            })}
 520→          </div>
 521→        </div>
 522→      </div>
 523→    </s-section>
 524→  );
 525→}
 526→
 527→// ---------------------------------------------------------------------------
 528→// Main component
 529→// ---------------------------------------------------------------------------
 530→
 531→export default function SizeCharts() {
 532→  const { charts, plan, templates, categories, canCreate } =
 533→    useLoaderData<typeof loader>();
 534→  const fetcher = useFetcher<typeof action>();
 535→  const shopify = useAppBridge();
 536→
 537→  const [showTemplates, setShowTemplates] = useState(false);
 538→  const [showImport, setShowImport] = useState(false);
 539→  const [importName, setImportName] = useState("Imported Size Chart");
 540→  const [importCategory, setImportCategory] = useState("general");
 541→  const [importCsvText, setImportCsvText] = useState("");
 542→  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
 543→  const [categoryFilter, setCategoryFilter] = useState("all");
 544→  const [searchQuery, setSearchQuery] = useState("");
 545→
 546→  const isLoading = fetcher.state !== "idle";
 547→
 548→  useEffect(() => {
 549→    if (!fetcher.data) return;
 550→    const data = fetcher.data as ActionData;
 551→    if ("ok" in data && data.ok) {
 552→      shopify.toast.show(data.message);
 553→      if ("redirectId" in data && data.redirectId) {
 554→        window.location.href = `/app/size-charts/${data.redirectId}`;
 555→      } else {
 556→        setShowTemplates(false);
 557→        setShowImport(false);
 558→        setImportCsvText("");
 559→        setImportName("Imported Size Chart");
 560→      }
 561→    } else if ("error" in data) {
 562→      shopify.toast.show(data.error, { isError: true });
 563→    }
 564→  }, [fetcher.data, shopify]);
 565→
 566→  const filteredCharts = charts.filter((chart) => {
 567→    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
 568→    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
 569→    const matchesSearch =
 570→      searchQuery.trim() === "" ||
 571→      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
 572→    return matchesStatus && matchesCategory && matchesSearch;
 573→  });
 574→
 575→  const publishedCount = charts.filter((c) => c.status === "active").length;
 576→  const draftCount = charts.filter((c) => c.status === "draft").length;
 577→  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
 578→  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
 579→  const maxCharts = plan.limits.maxCharts;
 580→  const isFreePlan = plan.id === "free";
 581→
 582→  const progressPct =
 583→    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
 584→  const progressColor =
 585→    publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";
 586→
 587→  function clearFilters() {
 588→    setStatusFilter("all");
 589→    setCategoryFilter("all");
 590→    setSearchQuery("");
 591→  }
 592→
 593→  return (
 594→    <s-page heading="Size Charts">
 595→      {/* Primary action */}
 596→      <s-button
 597→        slot="primary-action"
 598→        variant="primary"
 599→        onClick={() => setShowTemplates(!showTemplates)}
 600→        disabled={!canCreate || isLoading}
 601→      >
 602→        {canCreate
 603→          ? showTemplates
 604→            ? "Cancel"
 605→            : "Create chart"
 606→          : `Limit reached (${plan.limits.maxCharts})`}
 607→      </s-button>
 608→
 609→      <s-button
 610→        slot="secondary-action"
 611→        onClick={() => { setShowImport(!showImport); setShowTemplates(false); }}
 612→      >
 613→        Import CSV
 614→      </s-button>
 615→
 616→      {/* Subtitle */}
 617→      <s-text tone="neutral">
 618→        Manage your size charts and assign them to products
 619→      </s-text>
 620→
 621→      {/* ================================================================ */}
 622→      {/* PLAN LIMIT BANNER                                                 */}
 623→      {/* ================================================================ */}
 624→      {!canCreate && (
 625→        <s-section>
 626→          <s-banner tone="warning" heading="Chart limit reached">
 627→            You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
 628→            {plan.name} plan. Upgrade to Starter for unlimited charts with no
 629→            hidden fees.{" "}
 630→            <s-button href="/app/pricing" variant="primary">
 631→              Upgrade plan
 632→            </s-button>
 633→          </s-banner>
 634→        </s-section>
 635→      )}
 636→
 637→      {/* ================================================================ */}
 638→      {/* TEMPLATE PICKER                                                   */}
 639→      {/* ================================================================ */}
 640→      {showTemplates && (
 641→        <TemplatePicker
 642→          templates={templates}
 643→          categories={categories}
 644→          isLoading={isLoading}
 645→          onClose={() => setShowTemplates(false)}
 646→          fetcher={fetcher}
 647→        />
 648→      )}
 649→
 650→      {/* ================================================================ */}
 651→      {/* CSV IMPORT PANEL                                                  */}
 652→      {/* ================================================================ */}
 653→      {showImport && (
 654→        <s-section>
 655→          <s-box padding="base" borderWidth="base" borderRadius="base">
 656→            <s-stack direction="block" gap="base">
 657→              {/* Header row */}
 658→              <s-stack direction="inline" gap="base">
 659→                <s-stack direction="block" gap="small-200">
 660→                  <s-heading>Import Size Chart from CSV</s-heading>
 661→                  <s-text color="subdued">
 662→                    Paste your CSV data below. The first row must be column headers (e.g. Size, Chest, Waist).
 663→                  </s-text>
 664→                </s-stack>
 665→                <s-button variant="tertiary" onClick={() => setShowImport(false)}>Close</s-button>
 666→              </s-stack>
 667→
 668→              {/* CSV format hint */}
 669→              <s-box padding="base" borderWidth="base" borderRadius="base">
 670→                <s-stack direction="block" gap="small-200">
 671→                  <s-text color="subdued">
 672→                    <strong>Expected CSV format</strong>
 673→                  </s-text>
 674→                  <code style={{ fontSize: "12px", color: "#5c5f62", lineHeight: 1.7, display: "block", whiteSpace: "pre" }}>{`Size,Chest,Waist,Hips\nXS,32-34,24-26,34-36\nS,34-36,26-28,36-38\nM,36-38,28-30,38-40`}</code>
 675→                </s-stack>
 676→              </s-box>
 677→
 678→              {/* Name + category row */}
 679→              <s-stack direction="inline" gap="base">
 680→                <div style={{ flex: 2, minWidth: "180px" }}>
 681→                  <s-text-field
 682→                    label="Chart name"
 683→                    value={importName}
 684→                    onChange={(e: Event) => setImportName((e.target as HTMLInputElement).value)}
 685→                    placeholder="e.g. Women's Tops"
 686→                  />
 687→                </div>
 688→                <div style={{ flex: 1, minWidth: "140px" }}>
 689→                  <s-select
 690→                    label="Category"
 691→                    value={importCategory}
 692→                    onChange={(e: Event) =>
 693→                      setImportCategory((e.target as HTMLSelectElement).value)
 694→                    }
 695→                  >
 696→                    <s-option value="general">General</s-option>
 697→                    <s-option value="tops">Tops</s-option>
 698→                    <s-option value="bottoms">Bottoms</s-option>
 699→                    <s-option value="dresses">Dresses</s-option>
 700→                    <s-option value="shoes">Shoes</s-option>
 701→                    <s-option value="kids">Kids</s-option>
 702→                    <s-option value="rings">Rings</s-option>
 703→                    <s-option value="sportswear">Sportswear</s-option>
 704→                  </s-select>
 705→                </div>
 706→              </s-stack>
 707→
 708→              {/* CSV textarea */}
 709→              <s-text-area
 710→                label="CSV data"
 711→                value={importCsvText}
 712→                rows={8}
 713→                onChange={(e: Event) => setImportCsvText((e.target as HTMLTextAreaElement).value)}
 714→                placeholder={"Size,Chest,Waist,Hips\nXS,32-34,24-26,34-36\nS,34-36,26-28,36-38"}
 715→              />
 716→
 717→              {/* Import action */}
 718→              <s-stack direction="inline" gap="base">
 719→                <fetcher.Form method="post" style={{ display: "inline" }}>
 720→                  <input type="hidden" name="intent" value="import-csv" />
 721→                  <input type="hidden" name="name" value={importName} />
 722→                  <input type="hidden" name="category" value={importCategory} />
 723→                  <input type="hidden" name="csvData" value={importCsvText} />
 724→                  <s-button variant="primary" type="submit" loading={isLoading} disabled={!importCsvText.trim()}>
 725→                    Import chart
 726→                  </s-button>
 727→                </fetcher.Form>
 728→                <s-text color="subdued">
 729→                  Chart will be created as a draft — review and publish when ready.
 730→                </s-text>
 731→              </s-stack>
 732→            </s-stack>
 733→          </s-box>
 734→        </s-section>
 735→      )}
 736→
 737→      {/* ================================================================ */}
 738→      {/* SEARCH + FILTER BAR (only when charts exist)                     */}
 739→      {/* ================================================================ */}
 740→      {charts.length > 0 && (
 741→        <s-section>
 742→          <s-box padding="base" borderWidth="base" borderRadius="base">
 743→            <s-stack direction="block" gap="base">
 744→              {/* Search input */}
 745→              <s-search-field
 746→                label=""
 747→                placeholder="Search charts..."
 748→                value={searchQuery}
 749→                onChange={(e: Event) =>
 750→                  setSearchQuery((e.target as HTMLInputElement).value)
 751→                }
 752→              />
 753→
 754→              {/* Status filter buttons + Category dropdown */}
 755→              <s-stack direction="inline" gap="base">
 756→                {/* Status filter buttons */}
 757→                <s-button-group>
 758→                  {[
 759→                    { key: "all", label: `All (${charts.length})` },
 760→                    { key: "active", label: `Active (${activeFilteredCount})` },
 761→                    { key: "draft", label: `Draft (${draftFilteredCount})` },
 762→                  ].map((tab) => (
 763→                    <s-button
 764→                      key={tab.key}
 765→                      variant={statusFilter === tab.key ? "primary" : "tertiary"}
 766→                      onClick={() => setStatusFilter(tab.key as "all" | "active" | "draft")}
 767→                    >
 768→                      {tab.label}
 769→                    </s-button>
 770→                  ))}
 771→                </s-button-group>
 772→
 773→                {/* Category select */}
 774→                <s-select
 775→                  label="Category"
 776→                  value={categoryFilter}
 777→                  onChange={(e: Event) =>
 778→                    setCategoryFilter((e.target as HTMLSelectElement).value)
 779→                  }
 780→                >
 781→                  <s-option value="all">All</s-option>
 782→                  {categories.map((cat) => (
 783→                    <s-option key={cat} value={cat}>
 784→                      {CATEGORY_LABELS[cat] ?? cat}
 785→                    </s-option>
 786→                  ))}
 787→                </s-select>
 788→              </s-stack>
 789→            </s-stack>
 790→          </s-box>
 791→        </s-section>
 792→      )}
 793→
 794→      {/* ================================================================ */}
 795→      {/* CHARTS LIST                                                       */}
 796→      {/* ================================================================ */}
 797→      <s-section>
 798→        <s-box padding="base" borderWidth="base" borderRadius="base">
