 800→          {charts.length > 0 && (
 801→            <s-stack direction="inline" gap="small-200">
 802→              <s-heading>
 803→                Size Charts
 804→              </s-heading>
 805→              <s-text color="subdued">
 806→                ({filteredCharts.length}
 807→                {filteredCharts.length !== charts.length ? ` of ${charts.length}` : ""})
 808→              </s-text>
 809→            </s-stack>
 810→          )}
 811→
 812→          {/* Empty state — no charts at all */}
 813→          {charts.length === 0 && (
 814→            <s-stack direction="block" gap="base">
 815→              <s-text>📐</s-text>
 816→              <s-heading>Create your first size chart</s-heading>
 817→              <s-text tone="neutral">
 818→                Start by creating a size chart to help your customers find the right
 819→                size. Reduce size-related returns by up to 40% — get started in under
 820→                3 minutes using one of our pre-built templates.
 821→              </s-text>
 822→              <s-button variant="primary" onClick={() => setShowTemplates(true)}>
 823→                Create chart
 824→              </s-button>
 825→            </s-stack>
 826→          )}
 827→
 828→          {/* Empty state — filters applied but no results */}
 829→          {charts.length > 0 && filteredCharts.length === 0 && (
 830→            <s-stack direction="block" gap="base">
 831→              <s-text>🔍</s-text>
 832→              <s-heading>No charts match your filters</s-heading>
 833→              <s-text tone="neutral">
 834→                Try adjusting your search or filters to find what you are looking for.
 835→              </s-text>
 836→              <s-button onClick={clearFilters}>Clear filters</s-button>
 837→            </s-stack>
 838→          )}
 839→
 840→          {/* Chart rows */}
 841→          {filteredCharts.length > 0 && (
 842→            <div style={{ marginTop: "8px" }}>
 843→              {filteredCharts.map((chart, i) => (
 844→                <div
 845→                  key={chart.id}
 846→                  style={{
 847→                    padding: "14px 0",
 848→                    borderBottom:
 849→                      i === filteredCharts.length - 1
 850→                        ? "none"
 851→                        : "1px solid #f1f1f1",
 852→                  }}
 853→                >
 854→                  <s-stack direction="inline" gap="base">
 855→                    {/* Left: name + meta */}
 856→                    <div style={{ flex: 1, minWidth: 0 }}>
 857→                      <s-stack direction="block" gap="small-200">
 858→                        <s-link href={`/app/size-charts/${chart.id}`}>
 859→                          {chart.name}
 860→                        </s-link>
 861→                        <s-stack direction="inline" gap="small-200">
 862→                          <s-badge tone={chart.status === "active" ? "success" : "neutral"}>
 863→                            {chart.status === "active" ? "Active" : "Draft"}
 864→                          </s-badge>
 865→                          <s-badge tone="info">
 866→                            {CATEGORY_LABELS[chart.category] ?? chart.category}
 867→                          </s-badge>
 868→                          <s-text color="subdued">
 869→                            {chart.assignments.length > 0
 870→                              ? `${chart.assignments.length} product${chart.assignments.length !== 1 ? "s" : ""} assigned`
 871→                              : "No assignments"}
 872→                          </s-text>
 873→                          <s-text color="subdued">
 874→                            Updated {formatDate(chart.updatedAt)}
 875→                          </s-text>
 876→                        </s-stack>
 877→                      </s-stack>
 878→                    </div>
 879→
 880→                    {/* Right: actions */}
 881→                    <s-stack direction="inline" gap="small-200">
 882→                      <s-button href={`/app/size-charts/${chart.id}`} variant="tertiary">
 883→                        Edit
 884→                      </s-button>
 885→
 886→                      <fetcher.Form method="post">
 887→                        <input type="hidden" name="intent" value="toggle-status" />
 888→                        <input type="hidden" name="id" value={chart.id} />
 889→                        <s-button type="submit" loading={isLoading}>
 890→                          {chart.status === "active" ? "Unpublish" : "Publish"}
 891→                        </s-button>
 892→                      </fetcher.Form>
 893→
 894→                      <fetcher.Form method="post">
 895→                        <input type="hidden" name="intent" value="duplicate" />
 896→                        <input type="hidden" name="id" value={chart.id} />
 897→                        <s-button type="submit" loading={isLoading}>
 898→                          Duplicate
 899→                        </s-button>
 900→                      </fetcher.Form>
 901→
 902→                      <fetcher.Form method="post">
 903→                        <input type="hidden" name="intent" value="delete" />
 904→                        <input type="hidden" name="id" value={chart.id} />
 905→                        <s-button
 906→                          type="submit"
 907→                          variant="tertiary"
 908→                          tone="critical"
 909→                          loading={isLoading}
 910→                        >
 911→                          Delete
 912→                        </s-button>
 913→                      </fetcher.Form>
 914→                    </s-stack>
 915→                  </s-stack>
 916→                </div>
 917→              ))}
 918→            </div>
 919→          )}
 920→        </s-box>
 921→      </s-section>
 922→
 923→      {/* ================================================================ */}
 924→      {/* ASIDE — Chart Limits                                              */}
 925→      {/* ================================================================ */}
 926→      <s-section slot="aside" heading="Chart limits">
 927→        <s-box padding="base" borderWidth="base" borderRadius="base">
 928→          <s-stack direction="block" gap="base">
 929→            {/* Plan badge row */}
 930→            <s-stack direction="inline" gap="base">
 931→              <s-badge tone={isFreePlan ? "neutral" : "success"}>
 932→                {plan.name} Plan
 933→              </s-badge>
 934→              {plan.price > 0 && (
 935→                <s-text color="subdued">${plan.price}/mo</s-text>
 936→              )}
 937→            </s-stack>
 938→
 939→            {maxCharts === -1 ? (
 940→              <s-text color="subdued">Unlimited charts on your plan.</s-text>
 941→            ) : (
 942→              <s-stack direction="block" gap="small-200">
 943→                <s-stack direction="inline" gap="base">
 944→                  <s-text>
 945→                    {publishedCount} / {maxCharts} published
 946→                  </s-text>
 947→                  <s-text color="subdued">{draftCount} draft</s-text>
 948→                </s-stack>
 949→                {/* Progress bar — keep as-is, no Polaris component available */}
 950→                <div
 951→                  style={{
 952→                    height: "6px",
 953→                    background: "#e4e5e7",
 954→                    borderRadius: "3px",
 955→                    overflow: "hidden",
 956→                  }}
 957→                >
 958→                  <div
 959→                    style={{
 960→                      height: "100%",
 961→                      width: `${progressPct}%`,
 962→                      background: progressColor,
 963→                      borderRadius: "3px",
 964→                      transition: "width 0.3s ease",
 965→                    }}
 966→                  />
 967→                </div>
 968→                <s-text color="subdued">
 969→                  {maxCharts - publishedCount > 0
 970→                    ? `${maxCharts - publishedCount} slot${maxCharts - publishedCount !== 1 ? "s" : ""} remaining`
 971→                    : "Limit reached — upgrade for more"}
 972→                </s-text>
 973→                <s-button href="/app/pricing" variant="primary">
 974→                  Upgrade for unlimited
 975→                </s-button>
 976→              </s-stack>
 977→            )}
 978→          </s-stack>
 979→        </s-box>
 980→      </s-section>
 981→
 982→      {/* ================================================================ */}
 983→      {/* ASIDE — Quick Tips                                                */}
 984→      {/* ================================================================ */}
 985→      <s-section slot="aside" heading="Quick tips">
 986→        <s-unordered-list>
 987→          <s-list-item>
 988→            Assign charts to products or collections for automatic display in your
 989→            storefront widget
 990→          </s-list-item>
 991→          <s-list-item>
 992→            Templates include standard sizing data so you can get started fast
 993→          </s-list-item>
 994→          <s-list-item>
 995→            Publish a chart to make it visible to customers on your store
 996→          </s-list-item>
 997→          <s-list-item>
 998→            Add both inch and centimeter values for international shoppers
 999→          </s-list-item>
1000→        </s-unordered-list>
1001→      </s-section>
1002→    </s-page>
1003→  );
1004→}
