                        <s-button type="submit" loading={isLoading}>
                          Duplicate
                        </s-button>
                      </fetcher.Form>

                      <fetcher.Form method="post" style={{ display: "contents" }}>
                        <input type="hidden" name="intent" value="delete" />
                        <input type="hidden" name="id" value={chart.id} />
                        <s-button
                          type="submit"
                          tone="critical"
                          loading={isLoading}
                        >
                          Delete
                        </s-button>
                      </fetcher.Form>
                    </s-button-group>
                  </s-stack>

                  {/* Bottom row: metadata */}
                  <s-stack direction="inline" gap="small-200">
                    <s-text color="subdued">
                      {chart.assignments.length > 0
                        ? `${chart.assignments.length} product${chart.assignments.length !== 1 ? "s" : ""} assigned`
                        : "No assignments"}
                    </s-text>
                    <s-text color="subdued">
                      Updated {formatDate(chart.updatedAt)}
                    </s-text>
                  </s-stack>
                </s-stack>
              </s-box>
            ))}

          </s-stack>
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* PLAN USAGE (inline, compact)                                      */}
      {/* ================================================================ */}
      {isFreePlan && maxCharts > 0 && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="inline" gap="base">
              <s-badge tone="neutral">{plan.name} Plan</s-badge>
              <s-text>{publishedCount} / {maxCharts} published</s-text>
              <div style={{ flex: 1, maxWidth: "200px", alignSelf: "center" }}>
                <div style={{ height: "6px", background: "#e4e5e7", borderRadius: "3px", overflow: "hidden" }}>
                  <div style={{ height: "100%", width: `${progressPct}%`, background: progressColor, borderRadius: "3px", transition: "width 0.3s ease" }} />
                </div>
              </div>
              <s-text color="subdued">
                {maxCharts - publishedCount > 0
                  ? `${maxCharts - publishedCount} slot${maxCharts - publishedCount !== 1 ? "s" : ""} left`
                  : "Limit reached"}
              </s-text>
              <s-button href="/app/pricing">Upgrade</s-button>
            </s-stack>
          </s-box>
        </s-section>
      )}
    </s-page>
  );
}

