              <s-text color="subdued">
                Our algorithm uses statistical body proportion models to estimate bust, waist, and hip measurements from the customer's inputs.
              </s-text>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-stack direction="inline" gap="small-200">
                <s-badge tone="info">Step 3</s-badge>
                <s-text>Best size shown</s-text>
              </s-stack>
              <s-text color="subdued">
                The closest size from your chart is returned with a confidence percentage and one or two alternative sizes.
              </s-text>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* SECTION 3 — Algorithm Selection                                   */}
      {/* ================================================================ */}
      <s-section heading="Algorithm">
        <s-stack direction="block" gap="small-200">
          <s-text color="subdued">
            Choose the recommendation algorithm. Changes are saved immediately.
          </s-text>
          <s-stack direction="inline" gap="base">
            <AlgorithmCard
              id="basic"
              label="Basic (Statistical)"
              description="Statistical body proportion model built from thousands of measurements. Fast and accurate with no training data required."
              badge="Included in Growth"
              badgeTone="success"
              selected={algorithm === "basic"}
              disabled={false}
              onSelect={submitAlgorithm}
            />
            <AlgorithmCard
              id="advanced"
              label="Advanced ML"
              description="Machine learning model that improves over time using your store's return and exchange data for higher accuracy."
              badge={canUseAdvanced ? "Included in Pro" : "Requires Pro — $19.99/mo"}
              badgeTone={canUseAdvanced ? "success" : "warning"}
              selected={algorithm === "advanced"}
              disabled={!canUseAdvanced}
              onSelect={submitAlgorithm}
            />
          </s-stack>
          {!canUseAdvanced && (
            <s-text color="subdued">
              Advanced ML is available on the Pro plan. <s-link href="/app/pricing">Upgrade to Pro — $19.99/mo</s-link>
            </s-text>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* SECTION 4 — Body Type Configuration                               */}
      {/* ================================================================ */}
      <s-section heading="Body Types">
        <s-stack direction="block" gap="small-200">
          <s-text color="subdued">
            Choose which body types customers can select in the recommendation form. Changes are saved immediately.
          </s-text>
          <s-stack direction="inline" gap="base">
            {bodyTypes.map((bt) => (
              <s-box key={bt.id} padding="base" borderWidth={bt.enabled ? "large" : "base"} borderRadius="base" background={bt.enabled ? "strong" : undefined}>
                <s-stack direction="block" gap="small-200">
                  <s-stack direction="inline" gap="base">
                    <s-stack direction="block" gap="small-200">
                      <s-text>{bt.label}</s-text>
                      <s-text color="subdued">{bt.description}</s-text>
                    </s-stack>
                    <s-switch
                      checked={bt.enabled}
                      onChange={(e: Event) => toggleBodyType(bt.id, (e.target as HTMLInputElement).checked)}
                    />
                  </s-stack>
                  {bt.enabled && <s-badge tone="success">Shown to customers</s-badge>}
                </s-stack>
              </s-box>
            ))}
          </s-stack>
          {bodyTypes.filter((bt) => bt.enabled).length === 0 && (
            <s-banner tone="warning" heading="No body types enabled">
              <s-text color="subdued">Enable at least one body type so customers can use the recommender.</s-text>
            </s-banner>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* SECTION 5 — Fit Preference                                         */}
      {/* ================================================================ */}
      <s-section heading="Fit Preference Bias">
        <s-stack direction="block" gap="small-200">
          <s-text color="subdued">
            Set the default fit bias for your store. This shifts recommendations toward larger or smaller sizes depending on your typical customer preference.
          </s-text>
          <s-stack direction="inline" gap="base">
            {FIT_OPTIONS.map((opt) => (
              <FitCard
                key={opt.id}
                id={opt.id}
                label={opt.label}
                description={opt.description}
                selected={fitPreference === opt.id}
                onSelect={(v) => setFitPreference(v)}
              />
            ))}
          </s-stack>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* SECTION 6 — Custom Sizing Rules                                   */}
      {/* ================================================================ */}
      <s-section heading="Sizing Rules">
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="block" gap="base">
            <s-stack direction="block" gap="small-200">
              <s-text>When customer is between two sizes</s-text>
              <s-text color="subdued">
                If measurements fall exactly between two sizes, recommend the smaller or the larger one.
              </s-text>
              <s-select
                label=""
                value={betweenSizes}
                onChange={(e: Event) => setBetweenSizes((e.target as HTMLSelectElement).value)}
              >
                <s-option value="smaller">Recommend smaller size</s-option>
                <s-option value="larger">Recommend larger size</s-option>
              </s-select>
            </s-stack>

            <s-button
              variant="primary"
              onClick={submitSizingRules}
              loading={isLoading && fetcher.formData?.get("intent") === "save-sizing-rules"}
            >
              Save sizing rules
            </s-button>
          </s-stack>
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* SECTION 7 — Test Recommendation                                   */}
      {/* ================================================================ */}
      <s-section heading="Test Recommendation">
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="block" gap="base">
            <s-text color="subdued">
              Enter sample customer inputs to preview what your recommender would suggest. This uses the saved algorithm and sizing rules.
            </s-text>

            <s-stack direction="inline" gap="base">
              <s-stack direction="block" gap="small-200">
                <s-text>Chart to test against</s-text>
                {charts.length === 0 ? (
                  <s-text color="subdued">No active charts. <s-link href="/app/size-charts">Create a chart</s-link> first.</s-text>
                ) : (
                  <s-select
                    label=""
                    value={testChartId}
                    onChange={(e: Event) => setTestChartId((e.target as HTMLSelectElement).value)}
                  >
                    {charts.map((c) => (
                      <s-option key={c.id} value={c.id}>{c.name} ({c.category})</s-option>
                    ))}
                  </s-select>
                )}
              </s-stack>

              <s-stack direction="block" gap="small-200">
                <s-text>Gender</s-text>
                <s-select
                  label=""
                  value={testGender}
                  onChange={(e: Event) => setTestGender((e.target as HTMLSelectElement).value)}
                >
                  <s-option value="female">Female</s-option>
                  <s-option value="male">Male</s-option>
                  <s-option value="unisex">Unisex</s-option>
                </s-select>
              </s-stack>

              <s-stack direction="block" gap="small-200">
                <s-text>Body type</s-text>
                <s-select
                  label=""
                  value={testBodyType}
                  onChange={(e: Event) => setTestBodyType((e.target as HTMLSelectElement).value)}
                >
                  {bodyTypes.filter((bt) => bt.enabled).map((bt) => (
                    <s-option key={bt.id} value={bt.id}>{bt.label}</s-option>
                  ))}
                </s-select>
              </s-stack>
            </s-stack>

            <s-stack direction="inline" gap="base">
              <s-number-field
                label="Height (cm)"
                value={testHeight}
                onChange={(e: Event) => setTestHeight((e.target as HTMLInputElement).value)}
                min={100}
                max={250}
              />
              <s-number-field
                label="Weight (kg)"
                value={testWeight}
                onChange={(e: Event) => setTestWeight((e.target as HTMLInputElement).value)}
                min={30}
                max={250}
              />
            </s-stack>

            <s-button
              variant="primary"
              onClick={submitTestRecommendation}
              loading={isLoading && fetcher.formData?.get("intent") === "test-recommendation"}
              disabled={charts.length === 0}
            >
              Test recommendation
            </s-button>

            {testResult && (
              <s-box padding="base" borderWidth="base" borderRadius="base">
                <s-stack direction="block" gap="small-200">
                  <s-stack direction="inline" gap="small-200">
                    <s-heading>{testResult.size}</s-heading>
                    <s-badge tone={testResult.confidence >= 85 ? "success" : testResult.confidence >= 70 ? "info" : "warning"}>
                      {testResult.confidence}% confidence
                    </s-badge>
                  </s-stack>
                  {testResult.alternatives.length > 0 && (
                    <s-stack direction="inline" gap="small-200">
                      <s-text color="subdued">Alternatives:</s-text>
                      {testResult.alternatives.map((alt) => (
                        <s-badge key={alt} tone="neutral">{alt}</s-badge>
                      ))}
                    </s-stack>
                  )}
                  <s-divider />
                  <s-text color="subdued">Estimated measurements</s-text>
                  <s-stack direction="inline" gap="base">
                    <s-stack direction="block" gap="small-200">
                      <s-text color="subdued">Bust</s-text>
                      <s-text>{testResult.bust} cm</s-text>
                    </s-stack>
                    <s-stack direction="block" gap="small-200">
                      <s-text color="subdued">Waist</s-text>
                      <s-text>{testResult.waist} cm</s-text>
                    </s-stack>
                    <s-stack direction="block" gap="small-200">
                      <s-text color="subdued">Hips</s-text>
                      <s-text>{testResult.hips} cm</s-text>
                    </s-stack>
                  </s-stack>
                </s-stack>
              </s-box>
            )}
          </s-stack>
        </s-box>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Current Plan                                               */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Current Plan">
        <s-stack direction="block" gap="small-200">
          <s-stack direction="inline" gap="small-200">
            <s-badge tone="success">{plan.name}</s-badge>
            <s-text color="subdued">${plan.price}/mo</s-text>
          </s-stack>
          <s-unordered-list>
            <s-list-item>
              <s-text color="subdued">Basic AI recommender</s-text>
              <s-badge tone="success">Included</s-badge>
            </s-list-item>
            <s-list-item>
              <s-text color="subdued">Advanced ML</s-text>
              <s-badge tone={canUseAdvanced ? "success" : "neutral"}>
                {canUseAdvanced ? "Included" : "Pro only"}
              </s-badge>
            </s-list-item>
          </s-unordered-list>
          {!canUseAdvanced && (
            <s-button href="/app/pricing">Upgrade for Advanced ML</s-button>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Performance Stats                                          */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Performance">
        <s-stack direction="block" gap="small-200">
          <s-text color="subdued">All computation is server-side. No third-party API calls means zero added latency and zero per-recommendation cost.</s-text>
          <s-unordered-list>
            <s-list-item>Basic algorithm: ~5ms response</s-list-item>
            <s-list-item>Advanced ML: ~50ms response</s-list-item>
            <s-list-item>Cost per recommendation: $0</s-list-item>
            <s-list-item>No customer data stored</s-list-item>
          </s-unordered-list>
          <s-badge tone="success">GDPR compliant</s-badge>
        </s-stack>
      </s-section>

    </s-page>
  );
}

