  1→import { useState, useEffect, useCallback } from "react";
  2→import type {
  3→  ActionFunctionArgs,
  4→  HeadersFunction,
  5→  LoaderFunctionArgs,
  6→} from "react-router";
  7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
  8→import { useAppBridge } from "@shopify/app-bridge-react";
  9→import { boundary } from "@shopify/shopify-app-react-router/server";
 10→import { authenticate } from "../shopify.server";
 11→import {
 12→  PLAN_STARTER_MONTHLY,
 13→  PLAN_STARTER_ANNUAL,
 14→  PLAN_PRO_MONTHLY,
 15→  PLAN_PRO_ANNUAL,
 16→  PLAN_ULTIMATE_MONTHLY,
 17→  PLAN_ULTIMATE_ANNUAL,
 18→} from "../plans";
 19→import {
 20→  cancelShopSubscription,
 21→  getShopSubscription,
 22→} from "../billing.server";
 23→import db from "../db.server";
 24→import {
 25→  Page,
 26→  Layout,
 27→  Card,
 28→  BlockStack,
 29→  InlineStack,
 30→  Text,
 31→  Badge,
 32→  Button,
 33→  ButtonGroup,
 34→  Divider,
 35→  Box,
 36→  Banner,
 37→  Icon,
 38→  Modal,
 39→  InlineGrid,
 40→} from "@shopify/polaris";
 41→import { CheckCircleIcon, StarIcon } from "@shopify/polaris-icons";
 42→
 43→// ─── Plan data ────────────────────────────────────────────────────────────────
 44→
 45→const PLANS_DATA = {
 46→  free: {
 47→    id: "free",
 48→    name: "Free",
 49→    monthlyPrice: 0,
 50→    annualPrice: 0,
 51→    annualMonthlyPrice: 0,
 52→    description: "Get started and try it out",
 53→    features: [
 54→      "Up to 20 zip codes",
 55→      "Allowed zip codes only",
 56→      "Basic storefront widget",
