 59→    ],
 60→    shopifyPlanMonthly: null as string | null,
 61→    shopifyPlanAnnual: null as string | null,
 62→  },
 63→  starter: {
 64→    id: "starter",
 65→    name: "Starter",
 66→    monthlyPrice: 4.99,
 67→    annualPrice: 39,
 68→    annualMonthlyPrice: 3.25,
 69→    description: "Essential features for small stores",
 70→    features: [
 71→      "Up to 500 zip codes",
