 93→      "Unlimited delivery rules",
 94→      "Full customer waitlist",
 95→      "Bulk CSV import & export",
 96→      "Cart & checkout blocking",
 97→      "Priority email support",
 98→    ],
 99→    shopifyPlanMonthly: PLAN_PRO_MONTHLY,
100→    shopifyPlanAnnual: PLAN_PRO_ANNUAL,
101→    bestValue: true,
102→  },
103→  ultimate: {
104→    id: "ultimate",
105→    name: "Ultimate",
106→    monthlyPrice: 19.99,
107→    annualPrice: 149,
108→    annualMonthlyPrice: 12.42,
109→    description: "Enterprise-grade power and flexibility",
110→    features: [
111→      "Everything in Pro",
