314→              </s-text>
315→            </s-stack>
316→          </s-box>
317→
318→          <s-box padding="base" borderWidth="base" borderRadius="base">
319→            <s-stack direction="block" gap="small-200">
320→              <s-heading>Mobile-First by Default</s-heading>
321→              <s-text color="subdued">
322→                iOS Safari bugs are the #1 complaint in competitor reviews. Our widget is built mobile-first from the ground up —
323→                pixel-perfect on every device, tested across all major browsers.
324→              </s-text>
325→            </s-stack>
326→          </s-box>
327→
328→          <s-box padding="base" borderWidth="base" borderRadius="base">
329→            <s-stack direction="block" gap="small-200">
330→              <s-heading>Set Up in Under 5 Minutes</s-heading>
331→              <s-text color="subdued">
332→                Auto-detect product types, suggest matching templates, and auto-assign charts — all in one flow.
333→                Most merchants publish their first chart in under 3 minutes.
334→              </s-text>
335→            </s-stack>
336→          </s-box>
337→        </s-stack>
338→      </s-section>
339→
340→      {/* ================================================================ */}
341→      {/* FEATURE COMPARISON TABLE (custom grid visualization)             */}
342→      {/* ================================================================ */}
343→      <s-section heading="Full Feature Comparison">
344→        <s-box padding="base" borderWidth="base" borderRadius="base">
345→          {/* Header row — custom layout requires div wrapper */}
346→          <div style={{ display: "flex", gap: "8px", paddingBottom: "8px" }}>
347→            <div style={{ flex: 2 }}>
348→              <s-text color="subdued">Feature</s-text>
349→            </div>
350→            {orderedPlans.map((plan) => (
351→              <div key={plan.id} style={{ flex: 1, textAlign: "center" }}>
352→                <s-stack direction="block" gap="small-100">
353→                  <s-text>{plan.name}</s-text>
354→                  <s-text color="subdued">{getPriceDisplay(plan)}</s-text>
355→                </s-stack>
356→              </div>
357→            ))}
358→          </div>
359→
360→          <s-divider />
361→
362→          {/* Feature rows */}
363→          {FEATURE_ROWS.map((row, rowIdx) => (
364→            <div
365→              key={row.key}
366→              style={{
367→                display: "flex",
368→                gap: "8px",
369→                padding: "8px 0",
370→                borderBottom: rowIdx < FEATURE_ROWS.length - 1 ? "1px solid #e4e5e7" : "none",
371→                alignItems: "center",
372→              }}
373→            >
374→              <div style={{ flex: 2 }}>
375→                <s-text>{row.label}</s-text>
376→              </div>
377→              {orderedPlans.map((plan) => {
378→                const val = plan.limits[row.key];
379→                let overrideText: string | null = null;
380→                let included: boolean;
381→                if (row.key === "maxCharts") {
382→                  included = true;
383→                  overrideText = val === -1 ? "Unlimited" : String(val);
384→                } else {
385→                  included = val as boolean;
386→                }
387→                return (
388→                  <div key={plan.id} style={{ flex: 1, display: "flex", justifyContent: "center" }}>
389→                    {overrideText ? (
390→                      <s-text>{overrideText}</s-text>
391→                    ) : (
392→                      <CheckIcon included={included} />
393→                    )}
394→                  </div>
395→                );
396→              })}
397→            </div>
398→          ))}
399→        </s-box>
400→      </s-section>
401→
402→      {/* ================================================================ */}
403→      {/* FAQ — inline, full width                                           */}
404→      {/* ================================================================ */}
405→      <s-section heading="Frequently Asked Questions">
406→        <s-box padding="base" borderWidth="base" borderRadius="base">
407→          <s-stack direction="block" gap="base">
408→            {[
409→              { q: "Can I switch plans anytime?", a: "Yes. Upgrade instantly — new features activate immediately. Downgrades take effect at end of billing period." },
410→              { q: "What happens to my charts if I downgrade?", a: "Charts are never deleted. On Free, only 3 most recent stay published. Re-publish anytime you upgrade." },
411→              { q: "Is there a free trial?", a: "The Free plan is permanent — not a trial. Upgrade when you need more features." },
412→              { q: "Are there per-order fees?", a: "Never. Flat monthly or annual pricing. No hidden charges, no matter how large your store grows." },
413→              { q: "Does the annual plan auto-renew?", a: "Yes. Cancel anytime from Shopify Admin → Settings → Billing. No cancellation fees." },
414→            ].map((faq) => (
415→              <s-stack key={faq.q} direction="block" gap="small-200">
416→                <s-text><strong>{faq.q}</strong></s-text>
417→                <s-text color="subdued">{faq.a}</s-text>
418→              </s-stack>
419→            ))}
420→          </s-stack>
421→        </s-box>
422→      </s-section>
423→    </s-page>
424→  );
425→}
