172→    subscription,
173→    appEmbedEnabled,
174→    activeThemeName,
175→    themeEditorUrl,
176→    themeEditorAppEmbedsUrl,
177→  } = useLoaderData<typeof loader>();
178→  const navigate = useNavigate();
179→  const { revalidate, state: revalidateState } = useRevalidator();
180→  const limits = PLAN_LIMITS[subscription.planTier];
181→
182→  // Dismissible onboarding — persisted in localStorage
183→  const [onboardingDismissed, setOnboardingDismissed] = useState(() => {
184→    try {
185→      return localStorage.getItem("zcc-onboarding-dismissed") === "true";
186→    } catch {
187→      return false;
188→    }
189→  });
190→  const handleDismissOnboarding = useCallback(() => {
191→    setOnboardingDismissed(true);
192→    try {
193→      localStorage.setItem("zcc-onboarding-dismissed", "true");
194→    } catch {
195→      // localStorage unavailable in some contexts
196→    }
197→  }, []);
198→  const isFreePlan = subscription.planTier === "free";
199→  const hasZipLimit = limits.maxZipCodes < UNLIMITED;
200→  const isEmpty = stats.total === 0;
201→
